screenPanels.initJs:
function(container, apiUrl, tables) {
  const tableIndex = 0; // 重複受注検出結果テーブル
  const tbody = container.querySelector("#duplicate-tbody");
  const comparisonPanel = container.querySelector("#comparison-panel");
  const comparisonEmpty = container.querySelector("#comparison-empty");
  const countDuplicates = container.querySelector("#count-duplicates");

  // Mock data for demonstration (in production, use tables[0].records)
  let allDuplicates = [
    {
      id: "dup-001",
      mainOrderId: "ORD-20250101-001",
      subOrderId: "ORD-20250101-002",
      customerName: "株式会社ABC",
      channel1: "Web注文",
      channel2: "電話受注",
      score: 95,
      status: "未確認",
      reason: "顧客名一致、電話番号一致、受注日時が同日",
      mainData: { orderId: "ORD-20250101-001", customer: "株式会社ABC", amount: "150,000", date: "2025-01-01 10:30", channel: "Web注文", items: "商品A×2" },
      subData: { orderId: "ORD-20250101-002", customer: "株式会社ABC", amount: "150,000", date: "2025-01-01 11:15", channel: "電話受注", items: "商品A×2" }
    },
    {
      id: "dup-002",
      mainOrderId: "ORD-20250102-003",
      subOrderId: "ORD-20250102-004",
      customerName: "株式会社XYZ",
      channel1: "店舗POS",
      channel2: "API連携",
      score: 78,
      status: "確認済み",
      reason: "金額一致、配送先一致",
      mainData: { orderId: "ORD-20250102-003", customer: "株式会社XYZ", amount: "75,000", date: "2025-01-02 14:00", channel: "店舗POS", items: "商品B×1" },
      subData: { orderId: "ORD-20250102-004", customer: "株式会社XYZ", amount: "75,000", date: "2025-01-02 14:05", channel: "API連携", items: "商品B×1" }
    },
    {
      id: "dup-003",
      mainOrderId: "ORD-20250103-005",
      subOrderId: "ORD-20250103-006",
      customerName: "個人顧客 田中太郎",
      channel1: "Web注文",
      channel2: "Web注文",
      score: 88,
      status: "未確認",
      reason: "顧客メールアドレス一致、受注日時が5分以内",
      mainData: { orderId: "ORD-20250103-005", customer: "個人顧客 田中太郎", amount: "25,000", date: "2025-01-03 09:00", channel: "Web注文", items: "商品C×3" },
      subData: { orderId: "ORD-20250103-006", customer: "個人顧客 田中太郎", amount: "25,000", date: "2025-01-03 09:05", channel: "Web注文", items: "商品C×3" }
    }
  ];

  function renderDuplicateList(rows) {
    tbody.innerHTML = rows.map(row => `
      <tr data-id="${row.id}" style="border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.2s;">
        <td style="padding: 8px 12px; border-right: 1px solid var(--border); color: var(--text);">${row.mainOrderId}</td>
        <td style="padding: 8px 12px; border-right: 1px solid var(--border); color: var(--text);">${row.customerName}</td>
        <td style="padding: 8px 12px; border-right: 1px solid var(--border); color: var(--text-muted); font-size: 11px;">${row.channel1} / ${row.channel2}</td>
        <td style="padding: 8px 12px; border-right: 1px solid var(--border); text-align: right; color: var(--primary); font-weight: 600;">${row.score}%</td>
        <td style="padding: 8px 12px; text-align: center;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; font-size: 10px; font-weight: 600; background: ${row.status === '未確認' ? 'rgba(255,165,0,0.2); color: #ffa500;' : row.status === '確認済み' ? 'rgba(76,175,80,0.2); color: #4caf50;' : 'rgba(100,100,100,0.2); color: #999;'}">${row.status}</span>
        </td>
      </tr>
    `).join("");
    countDuplicates.textContent = rows.length;
  }

  function showComparison(duplicateId) {
    const dup = allDuplicates.find(d => d.id === duplicateId);
    if (!dup) return;

    // Fill comparison header
    container.querySelector("#comp-main-id").textContent = dup.mainOrderId;
    container.querySelector("#comp-sub-id").textContent = dup.subOrderId;
    container.querySelector("#comp-reason").textContent = dup.reason;

    // Fill comparison table
    const compTbody = container.querySelector("#comparison-tbody");
    const fields = ["orderId", "customer", "amount", "date", "channel", "items"];
    const fieldLabels = { orderId: "受注ID", customer: "顧客名", amount: "金額", date: "受注日時", channel: "チャネル", items: "商品" };

    compTbody.innerHTML = fields.map(field => {
      const mainVal = dup.mainData[field] || "-";
      const subVal = dup.subData[field] || "-";
      const isDiff = mainVal !== subVal;
      return `
        <tr style="border-bottom: 1px solid var(--border);">
          <td style="padding: 8px 12px; color: var(--text-muted); font-weight: 600; background: rgba(0,0,0,0.1);">${fieldLabels[field]}</td>
          <td style="padding: 8px 12px; color: var(--text); ${isDiff ? 'background: rgba(255,165,0,0.1);' : ''}">${mainVal}</td>
          <td style="padding: 8px 12px; color: var(--text); ${isDiff ? 'background: rgba(255,165,0,0.1);' : ''}">${subVal}</td>
          <td style="padding: 8px 12px; text-align: center; color: ${isDiff ? '#ff6a00' : '#4caf50'}; font-weight: 600;">${isDiff ? '✕' : '○'}</td>
        </tr>
      `;
    }).join("");

    // Reset form
    container.querySelector("#comp-action").value = "";
    container.querySelector("#comp-status").value = "";
    container.querySelector("#comp-notes").value = "";

    // Show panel
    comparisonPanel.style.display = "block";
    comparisonEmpty.style.display = "none";
  }

  function hideComparison() {
    comparisonPanel.style.display = "none";
    comparisonEmpty.style.display = "block";
  }

  // Initial render
  renderDuplicateList(allDuplicates);

  // Search
  container.querySelector("#btn-search").addEventListener("click", () => {
    const keyword = container.querySelector("#input-search-keyword").value.toLowerCase();
    const channel = container.querySelector("#filter-channel").value;
    const scoreMin = parseInt(container.querySelector("#filter-score").value) || 0;
    const status = container.querySelector("#filter-status").value;

    const filtered = allDuplicates.filter(d => {
      const matchKeyword = !keyword || d.mainOrderId.toLowerCase().includes(keyword) || d.customerName.toLowerCase().includes(keyword);
      const matchChannel = !channel || d.channel1.includes(channel) || d.channel2.includes(channel);
      const matchScore = d.score >= scoreMin;
      const matchStatus = !status || d.status === status;
      return matchKeyword && matchChannel && matchScore && matchStatus;
    });

    renderDuplicateList(filtered);
  });

  // Row click to show comparison
  container.addEventListener("click", e => {
    const row = e.target.closest("tr[data-id]");
    if (row) {
      const id = row.dataset.id;
      showComparison(id);
    }
  });

  // Save comparison
  container.querySelector("#btn-save-comparison").addEventListener("click", async () => {
    const action = container.querySelector("#comp-action").value;
    const status = container.querySelector("#comp-status").value;
    const notes = container.querySelector("#comp-notes").value;

    if (!action || !status) {
      alert("対応方針と確認ステータスを選択してください");
      return;
    }

    // In production, save via window.aivicApi.update(tableIndex, id, {...})
    alert(`保存しました\n対応方針: ${action}\nステータス: ${status}\n備考: ${notes}`);
    hideComparison();
  });

  // Close comparison
  container.querySelector("#btn-close-comparison").addEventListener("click", hideComparison);

  // CSV Export
  container.querySelector("#btn-export").addEventListener("click", () => {
    const rows = allDuplicates;
    const headers = ["主受注ID", "副受注ID", "顧客名", "チャネル1", "チャネル2", "重複度スコア", "ステータス"];
    const csv = [
      "\uFEFF" + headers.join(","),
      ...rows.map(r => [r.mainOrderId, r.subOrderId, r.customerName, r.channel1, r.channel2, r.score, r.status].map(v => `"${v}"`).join(","))
    ].join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "duplicate-orders.csv";
    link.click();
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 修正対象優先度リスト = 0
  const tableIndex = 0;
  let allRows = [];
  let currentFilters = {
    priority: '',
    errorType: '',
    status: '',
    confidence: '',
    keyword: ''
  };
  let selectedRowId = null;

  // ユーザー情報表示（ダミー）
  container.querySelector('#user-name').textContent = 'システム管理者';

  // 再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#priority-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.08);"><td colspan="8" style="padding: 24px; text-align: center; color: var(--text-muted);">該当する修正対象がありません</td></tr>';
      updateStats(rows);
      return;
    }

    tbody.innerHTML = rows.map(r => {
      const priorityColor = r.優先度レベル === 1 ? '#ff6a56' : r.優先度レベル === 2 ? '#ff9a56' : r.優先度レベル === 3 ? '#ffc857' : '#9fb0d1';
      const statusColor = r.修正ステータス === '未対応' ? '#ff9a56' : r.修正ステータス === '対応中' ? '#ffc857' : r.修正ステータス === '完了' ? '#6dd5a8' : '#9fb0d1';
      const confidenceColor = r.信頼度スコア >= 70 ? '#6dd5a8' : r.信頼度スコア >= 40 ? '#ffc857' : '#ff9a56';

      return `
        <tr data-id="${r.優先度リストID}" style="border-bottom: 1px solid rgba(255,255,255,0.08); hover: background: rgba(255,255,255,0.04);">
          <td style="padding: 8px; color: var(--text);">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${priorityColor}20; color: ${priorityColor}; font-weight: 600; font-size: 11px;">
              ${r.優先度レベル}
            </span>
          </td>
          <td style="padding: 8px; color: var(--text); font-family: monospace; font-size: 11px;">${(r.受注データID || '').substring(0, 8)}</td>
          <td style="padding: 8px; color: var(--text); font-size: 11px;">${r.チャネル || '-'}</td>
          <td style="padding: 8px; color: var(--text); font-size: 11px; max-width: 300px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${r.エラー分類 || ''}">${r.エラー分類 || '-'}</td>
          <td style="padding: 8px; text-align: center; color: ${confidenceColor}; font-weight: 600; font-size: 11px;">${r.信頼度スコア || 0}%</td>
          <td style="padding: 8px; text-align: center;">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${statusColor}20; color: ${statusColor}; font-weight: 600; font-size: 11px;">
              ${r.修正ステータス || '未対応'}
            </span>
          </td>
          <td style="padding: 8px; text-align: center; color: var(--text-muted); font-size: 11px;">${r.検証実行日時 ? new Date(r.検証実行日時).toLocaleDateString('ja-JP', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : '-'}</td>
          <td style="padding: 8px; text-align: center; display: flex; gap: 4px; justify-content: center;">
            <button class="view-btn action-btn secondary" data-id="${r.優先度リストID}" style="padding: 4px 8px; font-size: 11px;">詳細</button>
            <button class="edit-btn action-btn secondary" data-id="${r.優先度リストID}" style="padding: 4px 8px; font-size: 11px;">編集</button>
          </td>
        </tr>
      `;
    }).join('');

    updateStats(rows);
  }

  // 統計情報更新
  function updateStats(rows) {
    const total = rows.length;
    const pending = rows.filter(r => r.修正ステータス === '未対応').length;
    const inprogress = rows.filter(r => r.修正ステータス === '対応中').length;
    const completed = rows.filter(r => r.修正ステータス === '完了').length;

    container.querySelector('#total-count').textContent = total;
    container.querySelector('#pending-count').textContent = pending;
    container.querySelector('#inprogress-count').textContent = inprogress;
    container.querySelector('#completed-count').textContent = completed;
  }

  // フィルタリング関数
  function applyFilters() {
    let filtered = allRows;

    if (currentFilters.priority) {
      filtered = filtered.filter(r => String(r.優先度レベル) === currentFilters.priority);
    }
    if (currentFilters.errorType) {
      filtered = filtered.filter(r => r.エラー分類 === currentFilters.errorType);
    }
    if (currentFilters.status) {
      filtered = filtered.filter(r => r.修正ステータス === currentFilters.status);
    }
    if (currentFilters.confidence) {
      const [min, max] = currentFilters.confidence.split('-').map(Number);
      filtered = filtered.filter(r => r.信頼度スコア >= min && r.信頼度スコア <= max);
    }
    if (currentFilters.keyword) {
      const kw = currentFilters.keyword.toLowerCase();
      filtered = filtered.filter(r => 
        (r.受注データID || '').toLowerCase().includes(kw) ||
        (r.エラー分類 || '').toLowerCase().includes(kw)
      );
    }

    // 優先度でソート
    filtered.sort((a, b) => (a.優先度レベル || 5) - (b.優先度レベル || 5));

    renderRows(filtered);
  }

  // 初期データ読み込み
  window.aivicApi.list(tableIndex).then(rows => {
    allRows = rows || [];
    applyFilters();
  });

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', () => {
    currentFilters.priority = container.querySelector('#priority-filter').value;
    currentFilters.errorType = container.querySelector('#error-type-filter').value;
    currentFilters.status = container.querySelector('#status-filter').value;
    currentFilters.confidence = container.querySelector('#confidence-filter').value;
    currentFilters.keyword = container.querySelector('#search-keyword').value;
    applyFilters();
  });

  // リセットボタン
  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelector('#priority-filter').value = '';
    container.querySelector('#error-type-filter').value = '';
    container.querySelector('#status-filter').value = '';
    container.querySelector('#confidence-filter').value = '';
    container.querySelector('#search-keyword').value = '';
    currentFilters = { priority: '', errorType: '', status: '', confidence: '', keyword: '' };
    applyFilters();
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', () => {
    const tbody = container.querySelector('#priority-tbody');
    const rows = Array.from(tbody.querySelectorAll('tr')).slice(0, -1);

    if (rows.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['優先度', '受注ID', 'チャネル', 'エラー内容', '信頼度スコア', '修正状態', '検出日時'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...allRows.map(r => [
        r.優先度レベル,
        r.受注データID,
        r.チャネル || '',
        r.エラー分類 || '',
        r.信頼度スコア || 0,
        r.修正ステータス || '',
        r.検証実行日時 ? new Date(r.検証実行日時).toLocaleString('ja-JP') : ''
      ].map(v => `"${String(v).replace(/"/g, '""')}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `修正対象優先度リスト_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 詳細・編集ボタン
  container.addEventListener('click', e => {
    const viewBtn = e.target.closest('.view-btn');
    const editBtn = e.target.closest('.edit-btn');

    if (viewBtn) {
      selectedRowId = viewBtn.dataset.id;
      const row = allRows.find(r => r.優先度リストID === selectedRowId);
      if (row) {
        container.querySelector('#modal-order-id').textContent = (row.受注データID || '').substring(0, 12);
        container.querySelector('#modal-priority').textContent = `${row.優先度レベル} (${['最高', '高', '中', '低', '最低'][row.優先度レベル - 1] || ''})`;
        container.querySelector('#modal-channel').textContent = row.チャネル || '-';
        container.querySelector('#modal-confidence').textContent = `${row.信頼度スコア || 0}%`;
        container.querySelector('#modal-error-content').textContent = row.エラー分類 || '-';
        container.querySelector('#modal-status').value = row.修正ステータス || '未対応';
        container.querySelector('#modal-notes').value = row.備考 || '';
        container.querySelector('#detail-modal').style.display = 'flex';
      }
    }

    if (editBtn) {
      selectedRowId = editBtn.dataset.id;
      const row = allRows.find(r => r.優先度リストID === selectedRowId);
      if (row) {
        container.querySelector('#modal-order-id').textContent = (row.受注データID || '').substring(0, 12);
        container.querySelector('#modal-priority').textContent = `${row.優先度レベル}`;
        container.querySelector('#modal-channel').textContent = row.チャネル || '-';
        container.querySelector('#modal-confidence').textContent = `${row.信頼度スコア || 0}%`;
        container.querySelector('#modal-error-content').textContent = row.エラー分類 || '-';
        container.querySelector('#modal-status').value = row.修正ステータス || '未対応';
        container.querySelector('#modal-notes').value = row.備考 || '';
        container.querySelector('#detail-modal').style.display = 'flex';
      }
    }
  });

  // モーダルクローズ
  container.querySelector('#modal-close').addEventListener('click', () => {
    container.querySelector('#detail-modal').style.display = 'none';
  });

  container.querySelector('#modal-cancel').addEventListener('click', () => {
    container.querySelector('#detail-modal').style.display = 'none';
  });

  // モーダル保存
  container.querySelector('#modal-save').addEventListener('click', async () => {
    if (!selectedRowId) return;

    const updatedStatus = container.querySelector('#modal-status').value;
    const updatedNotes = container.querySelector('#modal-notes').value;

    const result = await window.aivicApi.update(tableIndex, selectedRowId, {
      修正ステータス: updatedStatus,
      備考: updatedNotes
    });

    if (result) {
      window.aivicApi.list(tableIndex).then(rows => {
        allRows = rows || [];
        applyFilters();
      });
      container.querySelector('#detail-modal').style.display = 'none';
    }
  });

  // 詳細確認ボタン（他画面へ遷移）
  container.querySelector('#modal-detail').addEventListener('click', () => {
    if (selectedRowId) {
      const row = allRows.find(r => r.優先度リストID === selectedRowId);
      if (row && row.受注データID) {
        // 受注データ詳細確認・修正画面へ遷移
        window.showScreen('scr-1781413282852');
      }
    }
  });
}

function(container, apiUrl, tables) {
  // Table indices
  const TABLE_ORDERS = 0;
  const TABLE_VALIDATION = 1;
  const TABLE_DUPLICATES = 2;
  const TABLE_CONTRADICTIONS = 3;
  const TABLE_MISSING = 4;
  const TABLE_CORRECTION_HISTORY = 5;
  const TABLE_APPROVAL_FLOW = 6;
  const TABLE_APPROVAL_HISTORY = 7;
  const TABLE_OCR_RESULTS = 8;

  let selectedOrderId = null;
  let allOrders = [];
  let allValidationResults = [];
  let allDuplicates = [];
  let allContradictions = [];
  let allMissing = [];
  let allCorrectionHistory = [];
  let allApprovalFlows = [];
  let allOcrResults = [];

  // ===== 1. Render Functions =====

  function renderOrderList(orders) {
    const tbody = container.querySelector("#order-tbody");
    if (!orders || orders.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" style="padding: 1rem; text-align: center; color: var(--text-muted); font-size: 0.8125rem;">データなし</td></tr>';
      return;
    }
    tbody.innerHTML = orders.map(order => {
      const trustScore = order.trust_score || 0;
      const statusColor = order.validation_status === '合格' ? '#4ade80' : order.validation_status === '不合格' ? '#ef4444' : '#f59e0b';
      return `
        <tr data-id="${order.id}" style="cursor: pointer; background: rgba(255,255,255,0.02); border-bottom: 1px solid rgba(255,255,255,0.08);" onclick="this.style.background='rgba(255,255,255,0.08)';">
          <td style="padding: 0.5rem; color: var(--text); font-size: 0.8125rem;">${order.order_id || order.id?.substring(0, 8)}</td>
          <td style="padding: 0.5rem; color: var(--text); font-size: 0.8125rem;">${order.channel || 'N/A'}</td>
          <td style="padding: 0.5rem; color: var(--text); font-size: 0.8125rem;">
            <span style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 0.25rem; background: ${statusColor}20; color: ${statusColor}; font-weight: 500; font-size: 0.75rem;">
              ${order.validation_status || '未検証'}
            </span>
          </td>
          <td style="padding: 0.5rem; text-align: center; color: var(--text); font-size: 0.8125rem; font-weight: 600;">${trustScore}%</td>
        </tr>
      `;
    }).join('');

    // Add row click listeners
    container.querySelectorAll("#order-tbody tr[data-id]").forEach(row => {
      row.addEventListener("click", () => {
        selectedOrderId = row.dataset.id;
        renderValidationResults(selectedOrderId);
        renderCorrectionHistory(selectedOrderId);
      });
    });
  }

  function renderValidationResults(orderId) {
    const resultsContainer = container.querySelector("#validation-results");
    if (!orderId) {
      resultsContainer.innerHTML = '<div style="padding: 1rem; text-align: center; color: var(--text-muted); font-size: 0.8125rem;">受注を選択してください</div>';
      return;
    }

    const validation = allValidationResults.find(v => v.order_id === orderId || v.受注データID === orderId);
    const duplicates = allDuplicates.filter(d => d.primary_order_id === orderId || d.主受注ID === orderId);
    const contradictions = allContradictions.filter(c => (c.order_id_1 === orderId || c.受注ID_1 === orderId) || (c.order_id_2 === orderId || c.受注ID_2 === orderId));
    const missing = allMissing.filter(m => m.order_id === orderId || m.受注ID === orderId);

    let html = '';

    // Validation Result
    if (validation) {
      const errorColor = validation.severity === '致命的' ? '#ef4444' : validation.severity === '高' ? '#f97316' : '#f59e0b';
      html += `
        <div style="background: rgba(0,0,0,0.3); border-left: 3px solid ${errorColor}; padding: 0.75rem; border-radius: 0.25rem;">
          <div style="font-size: 0.75rem; color: var(--text-muted); margin-bottom: 0.25rem;">検証結果</div>
          <div style="font-size: 0.875rem; font-weight: 600; color: var(--text); margin-bottom: 0.5rem;">${validation.validation_status || '未検証'}</div>
          <div style="font-size: 0.8125rem; color: var(--text-muted); margin-bottom: 0.25rem;">
            <strong>項目:</strong> ${validation.validation_item || 'N/A'}
          </div>
          <div style="font-size: 0.8125rem; color: var(--text-muted); margin-bottom: 0.25rem;">
            <strong>エラー:</strong> ${validation.error_message || validation.エラーメッセージ || 'N/A'}
          </div>
          <div style="font-size: 0.8125rem; color: var(--text-muted);">
            <strong>重要度:</strong> <span style="color: ${errorColor}; font-weight: 600;">${validation.severity || validation.重要度 || 'N/A'}</span>
          </div>
        </div>
      `;
    }

    // Duplicate Detection
    if (duplicates.length > 0) {
      html += `
        <div style="background: rgba(0,0,0,0.3); border-left: 3px solid #f59e0b; padding: 0.75rem; border-radius: 0.25rem;">
          <div style="font-size: 0.75rem; color: var(--text-muted); margin-bottom: 0.25rem;">重複受注検出</div>
          <div style="font-size: 0.8125rem; color: var(--text);">
            ${duplicates.map(d => `
              <div style="margin-bottom: 0.25rem;">
                <strong>信頼度:</strong> ${d.matching_confidence || d.マッチング信頼度 || 0}% 
                <strong>理由:</strong> ${d.matching_reason || d.マッチング理由 || 'N/A'}
              </div>
            `).join('')}
          </div>
        </div>
      `;
    }

    // Channel Contradiction
    if (contradictions.length > 0) {
      html += `
        <div style="background: rgba(0,0,0,0.3); border-left: 3px solid #ef4444; padding: 0.75rem; border-radius: 0.25rem;">
          <div style="font-size: 0.75rem; color: var(--text-muted); margin-bottom: 0.25rem;">チャネル間矛盾検出</div>
          <div style="font-size: 0.8125rem; color: var(--text);">
            ${contradictions.map(c => `
              <div style="margin-bottom: 0.25rem;">
                <strong>矛盾タイプ:</strong> ${c.contradiction_type || c.矛盾タイプ || 'N/A'}<br/>
                <strong>内容:</strong> ${c.contradiction_content || c.矛盾内容 || 'N/A'}
              </div>
            `).join('')}
          </div>
        </div>
      `;
    }

    // Missing Fields
    if (missing.length > 0) {
      html += `
        <div style="background: rgba(0,0,0,0.3); border-left: 3px solid #f59e0b; padding: 0.75rem; border-radius: 0.25rem;">
          <div style="font-size: 0.75rem; color: var(--text-muted); margin-bottom: 0.25rem;">入力漏れ検出</div>
          <div style="font-size: 0.8125rem; color: var(--text);">
            ${missing.map(m => `
              <div style="margin-bottom: 0.25rem;">
                <strong>${m.missing_item_name || m.漏れ項目名}:</strong> ${m.missing_item_category || m.漏れ項目区分 || 'N/A'}
              </div>
            `).join('')}
          </div>
        </div>
      `;
    }

    if (!html) {
      html = '<div style="padding: 0.75rem; text-align: center; color: var(--text-muted); font-size: 0.8125rem;">検証結果がありません</div>';
    }

    resultsContainer.innerHTML = html;
  }

  function renderCorrectionHistory(orderId) {
    const historyContainer = container.querySelector("#correction-history");
    if (!orderId) {
      historyContainer.innerHTML = '<div style="padding: 0.75rem; text-align: center; color: var(--text-muted); font-size: 0.8125rem;">修正履歴がありません</div>';
      return;
    }

    const history = allCorrectionHistory.filter(h => h.order_id === orderId || h.受注データID === orderId);
    if (history.length === 0) {
      historyContainer.innerHTML = '<div style="padding: 0.75rem; text-align: center; color: var(--text-muted); font-size: 0.8125rem;">修正履歴がありません</div>';
      return;
    }

    historyContainer.innerHTML = history.map(h => `
      <div style="padding: 0.75rem; background: rgba(0,0,0,0.2); border-left: 2px solid var(--primary); border-radius: 0.25rem;">
        <div style="font-size: 0.75rem; color: var(--text-muted); margin-bottom: 0.25rem;">
          ${new Date(h.correction_date || h.修正日時).toLocaleString('ja-JP')}
        </div>
        <div style="font-size: 0.8125rem; color: var(--text); margin-bottom: 0.25rem;">
          <strong>${h.correction_item_name || h.修正項目名}:</strong> ${h.correction_reason || h.修正理由 || 'N/A'}
        </div>
        <div style="font-size: 0.75rem; color: var(--text-muted);">
          <strong>修正前:</strong> ${h.before_value || h.修正前値 || 'N/A'} → <strong>修正後:</strong> ${h.after_value || h.修正後値 || 'N/A'}
        </div>
      </div>
    `).join('');
  }

  // ===== 2. Load Initial Data =====

  async function loadAllData() {
    try {
      if (tables[TABLE_ORDERS]?.records) allOrders = tables[TABLE_ORDERS].records;
      if (tables[TABLE_VALIDATION]?.records) allValidationResults = tables[TABLE_VALIDATION].records;
      if (tables[TABLE_DUPLICATES]?.records) allDuplicates = tables[TABLE_DUPLICATES].records;
      if (tables[TABLE_CONTRADICTIONS]?.records) allContradictions = tables[TABLE_CONTRADICTIONS].records;
      if (tables[TABLE_MISSING]?.records) allMissing = tables[TABLE_MISSING].records;
      if (tables[TABLE_CORRECTION_HISTORY]?.records) allCorrectionHistory = tables[TABLE_CORRECTION_HISTORY].records;
      if (tables[TABLE_APPROVAL_FLOW]?.records) allApprovalFlows = tables[TABLE_APPROVAL_FLOW].records;
      if (tables[TABLE_OCR_RESULTS]?.records) allOcrResults = tables[TABLE_OCR_RESULTS].records;

      renderOrderList(allOrders);
    } catch (e) {
      console.error('Data load error:', e);
    }
  }

  loadAllData();

  // ===== 3. Search & Filter =====

  container.querySelector("#btn-search").addEventListener("click", () => {
    const orderId = container.querySelector("#input-order-id").value.trim();
    const channel = container.querySelector("#filter-channel").value;
    const status = container.querySelector("#filter-status").value;

    let filtered = allOrders;

    if (orderId) {
      filtered = filtered.filter(o => (o.order_id || o.id).includes(orderId));
    }
    if (channel) {
      filtered = filtered.filter(o => o.channel === channel);
    }
    if (status) {
      filtered = filtered.filter(o => o.validation_status === status);
    }

    renderOrderList(filtered);
  });

  // ===== 4. Approval Decision =====

  container.querySelector("#btn-approve").addEventListener("click", async () => {
    if (!selectedOrderId) {
      alert("受注を選択してください");
      return;
    }

    const decision = container.querySelector("#approval-decision").value;
    const priority = container.querySelector("#approval-priority").value;
    const comment = container.querySelector("#approval-comment").value;

    if (!decision || !priority) {
      alert("承認判定と優先度を選択してください");
      return;
    }

    try {
      const approvalRecord = {
        order_id: selectedOrderId,
        approval_decision: decision,
        priority: priority,
        approval_comment: comment,
        approval_date: new Date().toISOString(),
        approver_id: "current-user-id"
      };

      const saved = await window.aivicApi.save(TABLE_APPROVAL_HISTORY, approvalRecord);
      if (saved) {
        alert("承認判定を保存しました");
        container.querySelector("#approval-decision").value = "";
        container.querySelector("#approval-priority").value = "";
        container.querySelector("#approval-comment").value = "";
        loadAllData();
      }
    } catch (e) {
      console.error('Approval save error:', e);
    }
  });

  container.querySelector("#btn-cancel-approval").addEventListener("click", () => {
    container.querySelector("#approval-decision").value = "";
    container.querySelector("#approval-priority").value = "";
    container.querySelector("#approval-comment").value = "";
  });

  // ===== 5. OCR Confirmation Modal (Placeholder) =====

  // This would be triggered by a button in the validation results or a separate action
  // For now, it's just a modal structure ready to be populated

}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#result-tbody");
  const chartStatus = container.querySelector("#chart-status");
  const chartScore = container.querySelector("#chart-score");
  const kpiTotalCount = container.querySelector("[data-testid='kpi-total-count']");
  const kpiPassedCount = container.querySelector("[data-testid='kpi-passed-count']");
  const kpiFailedCount = container.querySelector("[data-testid='kpi-failed-count']");
  const kpiAvgScore = container.querySelector("[data-testid='kpi-avg-score']");

  // ステータスバッジの色付け
  function getStatusBadgeStyle(status) {
    const styles = {
      '合格': 'background: rgba(74, 222, 128, 0.15); color: #4ade80; border: 1px solid rgba(74, 222, 128, 0.3);',
      '不合格': 'background: rgba(255, 107, 107, 0.15); color: #ff6b6b; border: 1px solid rgba(255, 107, 107, 0.3);',
      '警告': 'background: rgba(251, 191, 36, 0.15); color: #fbbf24; border: 1px solid rgba(251, 191, 36, 0.3);',
      '保留': 'background: rgba(96, 165, 250, 0.15); color: #60a5fa; border: 1px solid rgba(96, 165, 250, 0.3);'
    };
    return styles[status] || 'background: rgba(156, 163, 175, 0.15); color: #9ca3af; border: 1px solid rgba(156, 163, 175, 0.3);';
  }

  // 優先度バッジの色付け
  function getPriorityBadgeStyle(priority) {
    const styles = {
      '1': 'background: rgba(255, 107, 107, 0.15); color: #ff6b6b;',
      '2': 'background: rgba(251, 191, 36, 0.15); color: #fbbf24;',
      '3': 'background: rgba(96, 165, 250, 0.15); color: #60a5fa;',
      '4': 'background: rgba(156, 163, 175, 0.15); color: #9ca3af;',
      '5': 'background: rgba(156, 163, 175, 0.15); color: #9ca3af;'
    };
    return styles[priority] || 'background: rgba(156, 163, 175, 0.15); color: #9ca3af;';
  }

  // 対応状況バッジの色付け
  function getResponseBadgeStyle(status) {
    const styles = {
      '未対応': 'background: rgba(156, 163, 175, 0.15); color: #9ca3af;',
      '対応中': 'background: rgba(96, 165, 250, 0.15); color: #60a5fa;',
      '完了': 'background: rgba(74, 222, 128, 0.15); color: #4ade80;',
      '却下': 'background: rgba(255, 107, 107, 0.15); color: #ff6b6b;'
    };
    return styles[status] || 'background: rgba(156, 163, 175, 0.15); color: #9ca3af;';
  }

  // テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id || ''}" style="border-bottom: 1px solid rgba(255,255,255,0.04); transition: background 0.2s;">
        <td style="padding: 8px 12px; color: var(--text); font-family: monospace; font-size: 12px;">${(r.受注データID || r.order_id || '').substring(0, 8)}</td>
        <td style="padding: 8px 12px; color: var(--text);">${r.チャネル名 || r.channel_name || '—'}</td>
        <td style="padding: 8px 12px;">
          <span style="padding: 3px 8px; border-radius: 3px; font-size: 12px; font-weight: 500; display: inline-block; ${getStatusBadgeStyle(r.検証ステータス || r.validation_status || '')}">
            ${r.検証ステータス || r.validation_status || '—'}
          </span>
        </td>
        <td style="padding: 8px 12px; color: var(--text); text-align: center; font-weight: 600;">${r.信頼度スコア || r.confidence_score || 0}%</td>
        <td style="padding: 8px 12px; color: var(--text-muted); font-size: 12px; max-width: 180px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${r.エラーメッセージ || r.error_message || '—'}">
          ${r.エラーメッセージ || r.error_message || '—'}
        </td>
        <td style="padding: 8px 12px; text-align: center;">
          <span style="padding: 3px 8px; border-radius: 3px; font-size: 12px; font-weight: 600; display: inline-block; ${getPriorityBadgeStyle(r.優先度レベル || r.priority_level || '')}">
            ${r.優先度レベル || r.priority_level || '—'}
          </span>
        </td>
        <td style="padding: 8px 12px;">
          <span style="padding: 3px 8px; border-radius: 3px; font-size: 12px; font-weight: 500; display: inline-block; ${getResponseBadgeStyle(r.対応状況 || r.response_status || '')}">
            ${r.対応状況 || r.response_status || '—'}
          </span>
        </td>
        <td style="padding: 8px 12px; text-align: center; display: flex; gap: 6px; justify-content: center;">
          <button class="action-btn secondary detail-btn" data-id="${r.id || ''}" style="padding: 4px 10px; font-size: 12px;">詳細</button>
          <button class="action-btn secondary edit-btn" data-id="${r.id || ''}" style="padding: 4px 10px; font-size: 12px;">編集</button>
        </td>
      </tr>
    `).join("");
  }

  // KPI 集計関数
  function updateKPIs(rows) {
    const total = rows.length;
    const passed = rows.filter(r => (r.検証ステータス || r.validation_status) === '合格').length;
    const failed = rows.filter(r => (r.検証ステータス || r.validation_status) === '不合格').length;
    const avgScore = total > 0 ? Math.round(rows.reduce((sum, r) => sum + (parseInt(r.信頼度スコア || r.confidence_score || 0) || 0), 0) / total) : 0;

    kpiTotalCount.textContent = total;
    kpiPassedCount.textContent = passed;
    kpiFailedCount.textContent = failed;
    kpiAvgScore.textContent = avgScore + '%';
  }

  // ステータス集計グラフ（円グラフ）
  function drawStatusChart(rows) {
    const ctx = chartStatus.getContext('2d');
    const statuses = {};
    rows.forEach(r => {
      const status = r.検証ステータス || r.validation_status || '不明';
      statuses[status] = (statuses[status] || 0) + 1;
    });

    const labels = Object.keys(statuses);
    const data = Object.values(statuses);
    const colors = ['#4ade80', '#ff6b6b', '#fbbf24', '#60a5fa'];

    const centerX = chartStatus.width / 2;
    const centerY = chartStatus.height / 2;
    const radius = Math.min(chartStatus.width, chartStatus.height) / 2 - 20;
    const total = data.reduce((a, b) => a + b, 0);

    let currentAngle = -Math.PI / 2;
    ctx.clearRect(0, 0, chartStatus.width, chartStatus.height);

    data.forEach((value, i) => {
      const sliceAngle = (value / total) * 2 * Math.PI;
      ctx.fillStyle = colors[i % colors.length];
      ctx.beginPath();
      ctx.arc(centerX, centerY, radius, currentAngle, currentAngle + sliceAngle);
      ctx.lineTo(centerX, centerY);
      ctx.fill();
      currentAngle += sliceAngle;
    });

    // ラベル描画
    ctx.fillStyle = '#d0e4ff';
    ctx.font = 'bold 11px sans-serif';
    ctx.textAlign = 'center';
    currentAngle = -Math.PI / 2;
    data.forEach((value, i) => {
      const sliceAngle = (value / total) * 2 * Math.PI;
      const labelAngle = currentAngle + sliceAngle / 2;
      const labelX = centerX + Math.cos(labelAngle) * (radius * 0.65);
      const labelY = centerY + Math.sin(labelAngle) * (radius * 0.65);
      ctx.fillText(labels[i], labelX, labelY);
      currentAngle += sliceAngle;
    });
  }

  // 信頼度スコア分布グラフ（ヒストグラム）
  function drawScoreChart(rows) {
    const ctx = chartScore.getContext('2d');
    const bins = [0, 0, 0, 0, 0]; // 0-20, 20-40, 40-60, 60-80, 80-100
    rows.forEach(r => {
      const score = parseInt(r.信頼度スコア || r.confidence_score || 0) || 0;
      const binIndex = Math.min(Math.floor(score / 20), 4);
      bins[binIndex]++;
    });

    const barWidth = chartScore.width / 5 - 8;
    const maxValue = Math.max(...bins, 1);
    const barHeight = (chartScore.height - 30) / maxValue;

    ctx.clearRect(0, 0, chartScore.width, chartScore.height);
    ctx.fillStyle = '#9ca3af';
    ctx.font = '11px sans-serif';
    ctx.textAlign = 'center';

    bins.forEach((value, i) => {
      const x = i * (barWidth + 8) + 4;
      const y = chartScore.height - 20 - value * barHeight;
      const h = value * barHeight;

      // バー描画
      ctx.fillStyle = ['#ff6b6b', '#fbbf24', '#60a5fa', '#4ade80', '#10b981'][i];
      ctx.fillRect(x, y, barWidth, h);

      // ラベル
      ctx.fillStyle = '#d0e4ff';
      ctx.fillText(value, x + barWidth / 2, chartScore.height - 5);
      ctx.fillStyle = '#9ca3af';
      ctx.fillText(`${i * 20}-${(i + 1) * 20}`, x + barWidth / 2, chartScore.height - 15);
    });
  }

  // 初期データ読み込み・描画
  window.aivicApi.list(0).then(rows => {
    if (rows && rows.length > 0) {
      renderRows(rows);
      updateKPIs(rows);
      drawStatusChart(rows);
      drawScoreChart(rows);
    }
  });

  // 検索ボタン
  container.querySelector("[data-testid='search-button']").addEventListener("click", async () => {
    const startDate = container.querySelector("[data-testid='filter-start-date']").value;
    const endDate = container.querySelector("[data-testid='filter-end-date']").value;
    const channel = container.querySelector("[data-testid='filter-channel']").value;

    const allRows = await window.aivicApi.list(0);
    let filtered = allRows || [];

    if (startDate) {
      const start = new Date(startDate);
      filtered = filtered.filter(r => {
        const execDate = new Date(r.検証実行日時 || r.validation_execution_datetime || '');
        return execDate >= start;
      });
    }

    if (endDate) {
      const end = new Date(endDate);
      filtered = filtered.filter(r => {
        const execDate = new Date(r.検証実行日時 || r.validation_execution_datetime || '');
        return execDate <= end;
      });
    }

    if (channel) {
      filtered = filtered.filter(r => (r.チャネル名 || r.channel_name || '').includes(channel));
    }

    renderRows(filtered);
    updateKPIs(filtered);
    drawStatusChart(filtered);
    drawScoreChart(filtered);
  });

  // CSV出力ボタン
  container.querySelector("[data-testid='export-button']").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows || rows.length === 0) {
      alert("出力するデータがありません");
      return;
    }

    const headers = ['受注ID', 'チャネル名', '検証ステータス', '信頼度スコア', 'エラーメッセージ', '優先度レベル', '対応状況'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...rows.map(r => [
        (r.受注データID || r.order_id || '').substring(0, 8),
        r.チャネル名 || r.channel_name || '',
        r.検証ステータス || r.validation_status || '',
        r.信頼度スコア || r.confidence_score || 0,
        `"${(r.エラーメッセージ || r.error_message || '').replace(/"/g, '""')}"`,
        r.優先度レベル || r.priority_level || '',
        r.対応状況 || r.response_status || ''
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `validation-report-${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 詳細ボタン
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      window.showScreen("scr-1781413282852"); // 受注データ詳細確認・修正画面
    }

    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      const id = editBtn.dataset.id;
      window.showScreen("scr-1781413354977"); // 修正対象優先度リスト画面
    }
  });
}

