          </td>
        </tr>
      `;
    }).join("");

    container.querySelector("#result-count").textContent = rows.length;
  }

  // 2. 初期データ描画
  if (tables[0] && tables[0].records) {
    renderRows(tables[0].records);
  }

  // 3. フィルタリング関数
  function applyFilters(allRows) {
    const minScore = parseInt(container.querySelector("#score-min-input").value) || 0;
    const maxScore = parseInt(container.querySelector("#score-max-input").value) || 100;
    const level = container.querySelector("#level-filter").value;
    const channel = container.querySelector("#channel-filter").value;
    const status = container.querySelector("#status-filter").value;
    const keyword = container.querySelector("#search-keyword").value.toLowerCase();
    const hasCorrection = container.querySelector("#has-correction").checked;
    const hasWarning = container.querySelector("#has-warning").checked;
    const ocrFilter = container.querySelector("#ocr-filter").value;
    const duplicateFilter = container.querySelector("#duplicate-filter").value;
    const conflictFilter = container.querySelector("#conflict-filter").value;

    return allRows.filter(r => {
      const score = r.総合スコア || r.total_score || 0;
      const scoreLevel = score >= 80 ? 'high' : score >= 60 ? 'medium' : 'low';

      // スコア範囲
      if (score < minScore || score > maxScore) return false;

      // レベル
      if (level && scoreLevel !== level) return false;

      // チャネル
      if (channel && (r.チャネル || r.channel) !== channel) return false;

      // ステータス
      if (status && (r.ステータス || r.status) !== status) return false;

      // キーワード検索
      if (keyword) {
        const orderId = (r.受注ID || r.order_id || '').toLowerCase();
        const customerName = (r.顧客名 || r.customer_name || '').toLowerCase();
        if (!orderId.includes(keyword) && !customerName.includes(keyword)) return false;
      }

      // 修正履歴有無
      if (hasCorrection && !(r.修正履歴有 || r.has_correction)) return false;

      // 警告フラグ
      if (hasWarning && !(r.警告フラグ || r.warning_flag)) return false;

      return true;
    });
  }

  // 4. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const allRows = await window.aivicApi.list(tableIndex) || tables[0].records || [];
    const filtered = applyFilters(allRows);
    renderRows(filtered);
  });

  // 5. リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#score-min-input").value = "0";
    container.querySelector("#score-max-input").value = "100";
    container.querySelector("#score-slider").value = "50";
    container.querySelector("#level-filter").value = "";
    container.querySelector("#channel-filter").value = "";
    container.querySelector("#status-filter").value = "";
    container.querySelector("#search-keyword").value = "";
    container.querySelector("#has-correction").checked = false;
    container.querySelector("#has-warning").checked = false;
    container.querySelector("#ocr-filter").value = "";
    container.querySelector("#duplicate-filter").value = "";
    container.querySelector("#conflict-filter").value = "";

    if (tables[0] && tables[0].records) {
      renderRows(tables[0].records);
    }
  });

  // 6. スライダー連動
  container.querySelector("#score-slider").addEventListener("input", (e) => {
    const val = e.target.value;
    container.querySelector("#score-min-display").textContent = "0";
    container.querySelector("#score-max-display").textContent = val;
    container.querySelector("#score-max-input").value = val;
  });

  // 7. CSVエクスポート
  container.querySelector("#btn-export-csv").addEventListener("click", async () => {
    const allRows = await window.aivicApi.list(tableIndex) || tables[0].records || [];
    const filtered = applyFilters(allRows);

    if (filtered.length === 0) {
      alert("エクスポート対象データがありません");
      return;
    }

    const headers = ["受注ID", "顧客名", "総合スコア", "完全性", "正確性", "一貫性", "チャネル", "ステータス", "警告"];
    const rows = filtered.map(r => [
      r.受注ID || r.order_id || '',
      r.顧客名 || r.customer_name || '',
      r.総合スコア || r.total_score || '',
      r.完全性スコア || r.completeness_score || '',
      r.正確性スコア || r.accuracy_score || '',
      r.一貫性スコア || r.consistency_score || '',
      r.チャネル || r.channel || '',
      r.ステータス || r.status || '',
      r.警告フラグ || r.warning_flag ? '有' : '無'
    ]);

    const csv = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `信頼度スコア_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 8. 詳細ボタン（行レベル操作）
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      // 詳細確認・修正画面へ遷移
      window.showScreen("scr-1781413282852");
    }
  });
}

function(container, apiUrl, tables) {
  // ステップ管理
  let currentStep = 1;
  const totalSteps = 4;

  // ステッパークリック
  container.querySelectorAll(".stepper-step").forEach(step => {
    step.addEventListener("click", () => {
      const stepNum = parseInt(step.dataset.step);
      if (stepNum <= currentStep) {
        currentStep = stepNum;
        updateStepper();
      }
    });
  });

  function updateStepper() {
    container.querySelectorAll(".stepper-step").forEach(step => {
      const stepNum = parseInt(step.dataset.step);
      if (stepNum === currentStep) {
        step.classList.add("active");
        step.style.background = "rgba(255, 215, 0, 0.1)";
        step.style.border = "1px solid rgba(255, 215, 0, 0.3)";
        step.style.opacity = "1";
      } else if (stepNum < currentStep) {
        step.classList.remove("active");
        step.style.background = "transparent";
        step.style.border = "1px solid var(--border)";
        step.style.opacity = "1";
      } else {
        step.classList.remove("active");
        step.style.background = "transparent";
        step.style.border = "1px solid var(--border)";
        step.style.opacity = "0.6";
      }
    });
  }

  // タブ切り替え
  container.querySelectorAll(".tab-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      const tabName = btn.dataset.tab;
      container.querySelectorAll(".tab-btn").forEach(b => {
        b.classList.remove("active");
        b.style.color = "var(--text-muted)";
        b.style.borderBottomColor = "transparent";
      });
      btn.classList.add("active");
      btn.style.color = "var(--text)";
      btn.style.borderBottomColor = "var(--primary)";

      container.querySelectorAll(".tab-content").forEach(content => {
        content.style.display = "none";
      });
      container.querySelector(`#tab-${tabName}`).style.display = "block";
    });
  });

  // ボタンイベント
  container.querySelector("[data-testid='next-button']").addEventListener("click", () => {
    if (currentStep < totalSteps) {
      currentStep++;
      updateStepper();
    }
  });

  container.querySelector("[data-testid='back-button']").addEventListener("click", () => {
    if (currentStep > 1) {
      currentStep--;
      updateStepper();
    }
  });

  container.querySelector("[data-testid='cancel-button']").addEventListener("click", () => {
    if (confirm("キャンセルしますか？")) {
      window.showScreen("scr-1781413262699");
    }
  });

  container.querySelector("[data-testid='register-button']").addEventListener("click", async () => {
    if (confirm("受注データを基幹システムに登録します。よろしいですか？")) {
      // 基幹システム連携ログを記録
      const logData = {
        order_id: "ORD-2024-001234",
        direction: "送信",
        status: "成功",
        timestamp: new Date().toISOString()
      };

      const saved = await window.aivicApi.save(0, logData);
      if (saved) {
        alert("受注データを登録しました。");
        window.showScreen("scr-1781413262699");
      }
    }
  });

  container.querySelector("[data-testid='approve-button']").addEventListener("click", async () => {
    const comment = prompt("承認コメントを入力してください:");
    if (comment !== null) {
      alert("承認しました: " + comment);
      // 承認者判定履歴を記録
      const historyData = {
        order_id: "ORD-2024-001234",
        result: "承認",
        reason: comment,
        timestamp: new Date().toISOString()
      };
      await window.aivicApi.save(0, historyData);
    }
  });

  container.querySelector("[data-testid='reject-button']").addEventListener("click", async () => {
    const reason = prompt("却下理由を入力してください:");
    if (reason !== null) {
      alert("却下しました: " + reason);
      const historyData = {
        order_id: "ORD-2024-001234",
        result: "却下",
        reason: reason,
        timestamp: new Date().toISOString()
      };
      await window.aivicApi.save(0, historyData);
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックスの特定
  const correctionHistoryTableIndex = tables.findIndex(t => t.tableName === '受注データ修正履歴');
  const validationResultTableIndex = tables.findIndex(t => t.tableName === '受注データ検証結果');
  const trustScoreTableIndex = tables.findIndex(t => t.tableName === '信頼度スコア');
  const approvalFlowTableIndex = tables.findIndex(t => t.tableName === '連携承認フロー');

  // 修正項目テーブルの再描画
  function renderCorrectionItems(rows) {
    const tbody = container.querySelector('#correction-items-tbody');
    if (!tbody) return;
    tbody.innerHTML = rows.map(r => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 6px 8px; color: var(--text);">${r.修正項目名 || ''}</td>
        <td style="padding: 6px 8px; color: #ef4444;">${r.修正前値 || ''}</td>
        <td style="padding: 6px 8px; color: #4ade80;">${r.修正後値 || ''}</td>
        <td style="padding: 6px 8px; color: var(--text-muted);">${r.修正理由 || ''}</td>
      </tr>
    `).join('');
  }

  // 修正履歴タイムラインの再描画
  function renderCorrectionHistory(rows) {
    const historyContainer = container.querySelector('[style*="max-height: 200px"]');
    if (!historyContainer || rows.length === 0) return;

    const timelineHtml = rows.slice(0, 10).map((r, idx) => `
      <div style="margin-bottom: 12px; position: relative;">
        <div style="position: absolute; left: -14px; top: 2px; width: 12px; height: 12px; background: var(--primary); border-radius: 50%; border: 2px solid var(--bg-main);"></div>
        <div style="font-size: 11px; color: var(--text-muted);">${r.修正日時 || ''}</div>
        <div style="font-size: 12px; color: var(--text); margin-top: 2px;">${r.修正項目名 || ''} を ${r.修正前値 || ''} → ${r.修正後値 || ''} に修正</div>
        <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">修正者: ${r.修正ユーザーID || 'システム'} | 理由: ${r.修正理由 || ''}</div>
      </div>
    `).join('');

    const timelineWrapper = historyContainer.querySelector('[style*="position: relative"]');
    if (timelineWrapper) {
      timelineWrapper.innerHTML = `
        <div style="position: absolute; left: 6px; top: 0; bottom: 0; width: 2px; background: rgba(255,255,255,0.1);"></div>
        ${timelineHtml}
      `;
    }
  }

  // 初期データ読み込み
  if (correctionHistoryTableIndex >= 0) {
    const historyRows = tables[correctionHistoryTableIndex].records || [];
    renderCorrectionItems(historyRows);
    renderCorrectionHistory(historyRows);
  }

  // 保存ボタンのイベントリスナー
  const saveBtn = container.querySelector('[data-testid="save-button"]');
  if (saveBtn) {
    saveBtn.addEventListener('click', async () => {
      const reason = container.querySelector('[data-testid="correction-reason-select"]').value;
      const notes = container.querySelector('[data-testid="correction-notes"]').value;

      if (!reason) {
        alert('修正理由を選択してください');
        return;
      }

      if (!notes.trim()) {
        alert('修正備考を入力してください');
        return;
      }

      // 修正履歴を保存
      if (correctionHistoryTableIndex >= 0) {
        const saved = await window.aivicApi.save(correctionHistoryTableIndex, {
          受注データID: 'ORD-2025-001234',
          修正項目名: '受注金額',
          修正前値: '¥150,000',
          修正後値: '¥180,000',
          修正理由: reason,
          修正備考: notes,
          修正ユーザーID: '田中太郎',
          修正日時: new Date().toISOString()
        });

        if (saved) {
          alert('修正内容を保存しました');
          // 履歴を再読み込み
          const updated = await window.aivicApi.list(correctionHistoryTableIndex);
          renderCorrectionHistory(updated);
          // フォームをリセット
          container.querySelector('[data-testid="correction-reason-select"]').value = '';
          container.querySelector('[data-testid="correction-notes"]').value = '';
        }
      }
    });
  }

  // キャンセルボタンのイベントリスナー
  const cancelBtn = container.querySelector('[data-testid="cancel-button"]');
  if (cancelBtn) {
    cancelBtn.addEventListener('click', () => {
      if (confirm('修正内容を破棄して戻りますか？')) {
        window.showScreen('scr-1781413282852'); // 受注データ詳細確認・修正画面へ遷移
      }
    });
  }
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#validation-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const resultCount = container.querySelector("#result-count");
  let allRows = [];
  let selectedRowId = null;

  // ステータスのバッジ色を返す関数
  function getStatusBadgeColor(status) {
    const colors = {
      "合格": "#4ade80",
      "不合格": "#ef4444",
      "警告": "#f59e0b",
      "保留": "#6b7280"
    };
    return colors[status] || "#9ca3af";
  }

  // 重要度のバッジ色を返す関数
  function getSeverityColor(severity) {
    const colors = {
      "致命的": "#dc2626",
      "高": "#f97316",
      "中": "#f59e0b",
      "低": "#84cc16"
    };
    return colors[severity] || "#9ca3af";
  }

  // テーブル再描画関数
  function renderRows(rows) {
    allRows = rows;
    resultCount.textContent = rows.length;
    tbody.innerHTML = rows.map(r => {
      const statusColor = getStatusBadgeColor(r.検証ステータス);
      const severityColor = getSeverityColor(r.重要度);
      return `
        <tr data-id="${r.検証結果ID}" style="border-bottom: 1px solid rgba(255,255,255,0.06); cursor: pointer; transition: background 0.15s;" onmouseover="this.style.background='rgba(255,255,255,0.04)'" onmouseout="this.style.background='transparent'">
          <td style="padding: 8px 12px; color: var(--text); font-family: monospace; font-size: 11px;">${r.受注データID ? r.受注データID.substring(0, 8) : "—"}</td>
          <td style="padding: 8px 12px;">
            <span style="display: inline-block; padding: 3px 8px; background: ${statusColor}; color: #fff; border-radius: 3px; font-size: 11px; font-weight: 600;">${r.検証ステータス || "—"}</span>
          </td>
          <td style="padding: 8px 12px; color: var(--text); font-size: 11px; font-family: monospace;">${r.エラーコード || "—"}</td>
          <td style="padding: 8px 12px;">
            <span style="display: inline-block; padding: 2px 6px; background: ${severityColor}; color: #fff; border-radius: 2px; font-size: 10px; font-weight: 600;">${r.重要度 || "—"}</span>
          </td>
          <td style="padding: 8px 12px; text-align: center; color: var(--primary); font-weight: 600; font-size: 12px;">${r.信頼度スコア || "—"}</td>
          <td style="padding: 8px 12px; color: var(--text); font-size: 11px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${r.検証項目 || "—"}</td>
        </tr>
      `;
    }).join("");
  }

  // 詳細パネル更新関数
  function updateDetailPanel(row) {
    selectedRowId = row.検証結果ID;
    container.querySelector("#detail-order-id").textContent = row.受注データID ? row.受注データID.substring(0, 12) : "—";
    container.querySelector("#detail-error-message").textContent = row.エラーメッセージ || "—";
    container.querySelector("#detail-actual-value").textContent = row.検証値 || "—";
    container.querySelector("#detail-expected-value").textContent = row.期待値 || "—";
    container.querySelector("#detail-suggestion").textContent = row.修正提案 || "修正提案なし";

    // スコア表示
    container.querySelector("#detail-score-total").textContent = row.総合スコア ? `${row.総合スコア}%` : "—";
    container.querySelector("#detail-score-completeness").textContent = row.完全性スコア ? `${row.完全性スコア}%` : "—";
    container.querySelector("#detail-score-accuracy").textContent = row.正確性スコア ? `${row.正確性スコア}%` : "—";
    container.querySelector("#detail-score-consistency").textContent = row.一貫性スコア ? `${row.一貫性スコア}%` : "—";

    // 重複受注警告
    const dupSection = container.querySelector("#duplicate-section");
    if (row.重複受注警告) {
      dupSection.style.display = "block";
      container.querySelector("#detail-duplicate-info").textContent = row.重複受注警告;
      container.querySelector("#detail-duplicate-btn").style.display = "block";
    } else {
      dupSection.style.display = "none";
      container.querySelector("#detail-duplicate-btn").style.display = "none";
    }

    // チャネル間矛盾
    const conflictSection = container.querySelector("#channel-conflict-section");
    if (row.チャネル間矛盾) {
      conflictSection.style.display = "block";
      container.querySelector("#detail-channel-conflict").textContent = row.チャネル間矛盾;
      container.querySelector("#detail-conflict-btn").style.display = "block";
    } else {
      conflictSection.style.display = "none";
      container.querySelector("#detail-conflict-btn").style.display = "none";
    }

    // 入力漏れ検出
    const missingSection = container.querySelector("#missing-section");
    if (row.入力漏れ検出) {
      missingSection.style.display = "block";
      container.querySelector("#detail-missing-items").textContent = row.入力漏れ検出;
    } else {
      missingSection.style.display = "none";
    }
  }

  // 初期データ描画
  renderRows(tables[0].records || []);

  // 行クリックで詳細表示
  tbody.addEventListener("click", e => {
    const tr = e.target.closest("tr");
    if (tr) {
      const id = tr.dataset.id;
      const row = allRows.find(r => r.検証結果ID === id);
      if (row) updateDetailPanel(row);
    }
  });

  // 検索ボタン
  container.querySelector("[data-testid='search-button']").addEventListener("click", () => {
    const statusFilter = container.querySelector("[data-testid='status-filter']").value;
    const channelFilter = container.querySelector("[data-testid='channel-filter']").value;
    const dateFrom = container.querySelector("[data-testid='date-from']").value;
    const dateTo = container.querySelector("[data-testid='date-to']").value;
    const searchKeyword = container.querySelector("[data-testid='search-input']").value.toLowerCase();

    let filtered = allRows.filter(r => {
      if (statusFilter && r.検証ステータス !== statusFilter) return false;
      if (channelFilter && r.チャネル !== channelFilter) return false;
      if (dateFrom && r.検証実行日時 < dateFrom) return false;
      if (dateTo && r.検証実行日時 > dateTo) return false;
      if (searchKeyword && !JSON.stringify(r).toLowerCase().includes(searchKeyword)) return false;
      return true;
    });

    renderRows(filtered);
  });

  // 自動検証実行ボタン
  container.querySelector("[data-testid='validate-button']").addEventListener("click", async () => {
    const btn = container.querySelector("[data-testid='validate-button']");
    const originalText = btn.textContent;
    btn.textContent = "検証中...";
    btn.disabled = true;

    // API呼び出し（検証実行）
    const result = await window.aivicApi.list(0);
    if (result) {
      renderRows(result);
      btn.textContent = "検証完了";
      setTimeout(() => {
        btn.textContent = originalText;
        btn.disabled = false;
      }, 1500);
    } else {
      btn.textContent = originalText;
      btn.disabled = false;
    }
  });

  // 詳細確認・修正ボタン
  container.querySelector("#detail-edit-btn").addEventListener("click", () => {
    if (selectedRowId) {
      window.showScreen("scr-1781413282852");
    }
  });

  // 重複比較ボタン
  container.querySelector("#detail-duplicate-btn").addEventListener("click", () => {
    if (selectedRowId) {
      window.showScreen("scr-1781413297335");
    }
  });

  // 矛盾詳細ボタン
  container.querySelector("#detail-conflict-btn").addEventListener("click", () => {
    if (selectedRowId) {
      window.showScreen("scr-1781413311177");
    }
  });
}

