      '修正完了': 'rgba(76, 175, 80, 0.6)',
      '再検証待ち': 'rgba(255, 152, 0, 0.6)',
      '検証中': 'rgba(33, 150, 243, 0.6)',
      '検証完了': 'rgba(76, 175, 80, 0.6)',
      '承認待ち': 'rgba(255, 193, 7, 0.6)'
    };
    return colors[status] || 'rgba(158, 158, 158, 0.6)';
  }

  // 2. 修正前後の差分表示
  function renderDiffView(orderId) {
    const diffView = container.querySelector("#diff-view");
    const noSelection = container.querySelector("#no-selection");
    const validationView = container.querySelector("#validation-view");
    const validationEmpty = container.querySelector("#validation-empty");

    // 修正履歴を取得
    const correctionRecords = (tables[CORRECTION_HISTORY_IDX]?.records || []).filter(r => r.受注データID === orderId);

    if (correctionRecords.length === 0) {
      diffView.style.display = "none";
      noSelection.style.display = "flex";
      validationView.style.display = "none";
      validationEmpty.style.display = "flex";
      return;
    }

    // 修正者情報を取得（最新の修正から）
    const latestCorrection = correctionRecords[correctionRecords.length - 1];
    container.querySelector("#modifier-name").textContent = latestCorrection.修正ユーザーID ? latestCorrection.修正ユーザーID.substring(0, 8) : '-';
    container.querySelector("#modifier-date").textContent = latestCorrection.修正日時 ? new Date(latestCorrection.修正日時).toLocaleString('ja-JP') : '-';
    container.querySelector("#modifier-reason").textContent = latestCorrection.修正理由 || '-';

    // 差分項目を表示
    const diffItemsContainer = container.querySelector("#diff-items");
    diffItemsContainer.innerHTML = correctionRecords.map(correction => `
      <div style="padding: 8px; background: rgba(0,0,0,0.2); border-radius: 4px; border-left: 3px solid var(--primary);">
        <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 4px;">
          <strong style="color: var(--text);">${correction.修正項目名}</strong>
        </div>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; font-size: 10px;">
          <div>
            <div style="color: var(--text-muted); margin-bottom: 2px;">修正前</div>
            <div style="padding: 4px; background: rgba(255,0,0,0.1); border-radius: 3px; color: var(--text); word-break: break-all;">
              ${correction.修正前値 || '(空)'}
            </div>
          </div>
          <div>
            <div style="color: var(--text-muted); margin-bottom: 2px;">修正後</div>
            <div style="padding: 4px; background: rgba(0,255,0,0.1); border-radius: 3px; color: var(--text); word-break: break-all;">
              ${correction.修正後値 || '(空)'}
            </div>
          </div>
        </div>
        <div style="font-size: 9px; color: var(--text-muted); margin-top: 4px;">
          備考: ${correction.修正備考 || '-'}
        </div>
      </div>
    `).join("");

    diffView.style.display = "block";
    noSelection.style.display = "none";
  }

  // 3. 検証結果の表示
  function renderValidationResults(orderId) {
    const validationView = container.querySelector("#validation-view");
    const validationEmpty = container.querySelector("#validation-empty");

    // 検証結果を取得
    const validationRecords = (tables[VALIDATION_RESULTS_IDX]?.records || []).filter(r => r.受注データID === orderId);
    const trustScoreRecord = (tables[TRUST_SCORE_IDX]?.records || []).find(r => r.受注データID === orderId);
    const duplicateRecords = (tables[DUPLICATE_DETECTION_IDX]?.records || []).filter(r => r.主受注ID === orderId || r.副受注ID === orderId);
    const conflictRecords = (tables[CONFLICT_DETECTION_IDX]?.records || []).filter(r => r.受注ID_1 === orderId || r.受注ID_2 === orderId);

    if (!validationRecords.length && !trustScoreRecord && !duplicateRecords.length && !conflictRecords.length) {
      validationView.style.display = "none";
      validationEmpty.style.display = "flex";
      return;
    }

    // 信頼度スコア表示
    if (trustScoreRecord) {
      container.querySelector("#score-total").textContent = trustScoreRecord.総合スコア || '-';
      container.querySelector("#score-completeness").textContent = trustScoreRecord.完全性スコア || '-';
      container.querySelector("#score-accuracy").textContent = trustScoreRecord.正確性スコア || '-';
      container.querySelector("#score-consistency").textContent = trustScoreRecord.一貫性スコア || '-';
      container.querySelector("#score-warning").textContent = trustScoreRecord.警告フラグ ? '⚠️ ' + (trustScoreRecord.警告レベル || '警告') : 'OK';
    }

    // エラー・警告リスト
    const errorContainer = container.querySelector("#error-list");
    const errorEmpty = container.querySelector("#error-empty");
    const errorItems = validationRecords.filter(v => v.検証ステータス !== '合格');

    if (errorItems.length > 0) {
      errorEmpty.style.display = "none";
      errorContainer.innerHTML = errorItems.map(error => `
        <div style="padding: 4px; background: ${error.重要度 === '致命的' ? 'rgba(244,67,54,0.15)' : 'rgba(255,152,0,0.15)'}; border-radius: 3px; border-left: 2px solid ${error.重要度 === '致命的' ? '#f44336' : '#ff9800'};">
          <div style="color: var(--text); font-weight: 500;">${error.検証項目}</div>
          <div style="color: var(--text-muted); font-size: 9px;">${error.エラーメッセージ || error.エラーコード}</div>
        </div>
      `).join("");
    } else {
      errorEmpty.style.display = "block";
      errorContainer.innerHTML = "";
    }

    // 重複受注検出
    const duplicateContainer = container.querySelector("#duplicate-list");
    const duplicateEmpty = container.querySelector("#duplicate-empty");

    if (duplicateRecords.length > 0) {
      duplicateEmpty.style.display = "none";
      duplicateContainer.innerHTML = duplicateRecords.map(dup => `
        <div style="padding: 4px; background: rgba(255,193,7,0.15); border-radius: 3px; border-left: 2px solid #ffc107;">
          <div style="color: var(--text); font-size: 10px;">信頼度: ${dup.マッチング信頼度}%</div>
          <div style="color: var(--text-muted); font-size: 9px;">${dup.マッチング理由}</div>
        </div>
      `).join("");
    } else {
      duplicateEmpty.style.display = "block";
      duplicateContainer.innerHTML = "";
    }

    // チャネル間矛盾検出
    const conflictContainer = container.querySelector("#conflict-list");
    const conflictEmpty = container.querySelector("#conflict-empty");

    if (conflictRecords.length > 0) {
      conflictEmpty.style.display = "none";
      conflictContainer.innerHTML = conflictRecords.map(conf => `
        <div style="padding: 4px; background: rgba(244,67,54,0.15); border-radius: 3px; border-left: 2px solid #f44336;">
          <div style="color: var(--text); font-size: 10px;">${conf.矛盾タイプ}</div>
          <div style="color: var(--text-muted); font-size: 9px;">${conf.矛盾内容}</div>
        </div>
      `).join("");
    } else {
      conflictEmpty.style.display = "block";
      conflictContainer.innerHTML = "";
    }

    validationView.style.display = "block";
    validationEmpty.style.display = "none";
  }

  // 4. 初期データ読み込み
  async function loadInitialData() {
    const validationResults = tables[VALIDATION_RESULTS_IDX]?.records || [];
    const correctionHistory = tables[CORRECTION_HISTORY_IDX]?.records || [];

    // 修正済みの受注IDを抽出
    const modifiedOrderIds = new Set(correctionHistory.map(r => r.受注データID));
    allOrders = Array.from(modifiedOrderIds).map(id => ({
      id,
      status: '修正完了'
    }));

    renderOrdersList(allOrders);
  }

  // 5. 受注行クリック時の処理
  container.addEventListener("click", e => {
    const row = e.target.closest("tr[data-id]");
    if (row) {
      currentOrderId = row.dataset.id;
      renderDiffView(currentOrderId);
      renderValidationResults(currentOrderId);
    }
  });

  // 6. 検索ボタン
  container.querySelector("#btn-search-orders").addEventListener("click", () => {
    const searchValue = container.querySelector("#search-order-id").value.toLowerCase();
    const statusFilter = container.querySelector("#filter-status").value;

    let filtered = allOrders;
    if (searchValue) {
      filtered = filtered.filter(o => o.id.toLowerCase().includes(searchValue));
    }
    if (statusFilter) {
      filtered = filtered.filter(o => o.status === statusFilter);
    }

    renderOrdersList(filtered);
  });

  // 7. 再検証実行ボタン
  container.querySelector("#btn-revalidate").addEventListener("click", async () => {
    if (!currentOrderId) {
      alert("受注を選択してください");
      return;
    }

    // 再検証処理をシミュレート（実際にはAPI呼び出し）
    alert("受注 " + currentOrderId.substring(0, 8) + " の再検証を実行しました");
    renderValidationResults(currentOrderId);
  });

  // 8. 承認ボタン
  container.querySelector("#btn-approve").addEventListener("click", async () => {
    if (!currentOrderId) {
      alert("受注を選択してください");
      return;
    }

    if (confirm("この受注データを承認しますか？")) {
      alert("承認しました");
      // 承認フロー画面へ遷移
      window.showScreen("scr-1781413369295");
    }
  });

  // 9. 却下ボタン
  container.querySelector("#btn-reject").addEventListener("click", async () => {
    if (!currentOrderId) {
      alert("受注を選択してください");
      return;
    }

    const reason = prompt("却下理由を入力してください:");
    if (reason) {
      alert("却下しました: " + reason);
    }
  });

  // 10. 戻るボタン
  container.querySelector("#btn-back").addEventListener("click", () => {
    window.showScreen("scr-1781413262699");
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#validation-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const detailContent = container.querySelector("#detail-content");
  const detailFormTemplate = container.querySelector("#detail-form-template");

  let allRows = [];
  let selectedRowId = null;

  // 1. 再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map((r, idx) => {
      const priorityLevel = r.優先度レベル || 3;
      const priorityColor = priorityLevel === 1 ? '#ff4444' : priorityLevel === 2 ? '#ff9900' : '#ffcc00';
      const severityColor = r.重要度 === '致命的' ? '#ff4444' : r.重要度 === '高' ? '#ff9900' : r.重要度 === '中' ? '#ffcc00' : '#66bb6a';

      return `
        <tr data-id="${r.検証結果ID || idx}" data-row-index="${idx}" style="border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.15s;">
          <td style="padding: 8px 12px; text-align: center;">
            <div style="display: inline-block; width: 24px; height: 24px; border-radius: 50%; background: ${priorityColor}; color: #fff; font-size: 11px; font-weight: 600; line-height: 24px; text-align: center;">${priorityLevel}</div>
          </td>
          <td style="padding: 8px 12px; color: var(--text); font-size: 12px; word-break: break-all;">${(r.受注データID || '').substring(0, 8)}</td>
          <td style="padding: 8px 12px; color: var(--text); font-size: 12px;">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: rgba(255,255,255,0.08); font-size: 11px;">${r.エラータイプ || r.検証ルールID || '不明'}</span>
          </td>
          <td style="padding: 8px 12px; color: var(--text); font-size: 12px;">${r.検証項目 || ''}</td>
          <td style="padding: 8px 12px; text-align: center;">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${severityColor}22; color: ${severityColor}; font-size: 11px; font-weight: 500;">${r.重要度 || '中'}</span>
          </td>
          <td style="padding: 8px 12px; color: var(--text); font-size: 12px;">${r.対応状況 || '未対応'}</td>
          <td style="padding: 8px 12px; text-align: center; color: var(--text); font-size: 12px; font-weight: 500;">${r.信頼度スコア || r.マッチング信頼度 || '—'}%</td>
        </tr>
      `;
    }).join("");

    // 行クリックで詳細表示
    tbody.querySelectorAll("tr").forEach(tr => {
      tr.addEventListener("click", () => {
        const rowId = tr.dataset.id;
        const rowIndex = parseInt(tr.dataset.rowIndex);
        selectedRowId = rowId;
        const row = rows[rowIndex];
        showDetail(row);

        // 選択行をハイライト
        tbody.querySelectorAll("tr").forEach(r => r.style.background = "");
        tr.style.background = "rgba(255,255,255,0.04)";
      });
    });
  }

  // 2. 詳細パネル表示
  function showDetail(row) {
    const clone = detailFormTemplate.content.cloneNode(true);

    // 検証結果情報を埋める
    clone.querySelector("#detail-validation-id").textContent = row.検証結果ID || '—';
    clone.querySelector("#detail-order-id").textContent = (row.受注データID || '—').substring(0, 12);
    clone.querySelector("#detail-error-type").textContent = row.エラータイプ || row.検証ルールID || '—';
    clone.querySelector("#detail-validation-item").textContent = row.検証項目 || '—';
    clone.querySelector("#detail-validation-value").textContent = row.検証値 || '—';
    clone.querySelector("#detail-expected-value").textContent = row.期待値 || '—';
    clone.querySelector("#detail-error-message").textContent = row.エラーメッセージ || '—';
    clone.querySelector("#detail-severity").textContent = row.重要度 || '中';
    clone.querySelector("#detail-confidence-score").textContent = (row.信頼度スコア || row.マッチング信頼度 || 0) + '%';

    // 修正フォームのイベント
    const correctedValueInput = clone.querySelector("[data-testid='corrected-value-input']");
    const correctionReasonSelect = clone.querySelector("[data-testid='correction-reason-select']");
    const correctionNotesTextarea = clone.querySelector("[data-testid='correction-notes-textarea']");
    const confirmBtn = clone.querySelector("[data-testid='confirm-correction-button']");
    const rejectBtn = clone.querySelector("[data-testid='reject-correction-button']");

    confirmBtn.addEventListener("click", async () => {
      const correctedValue = correctedValueInput.value.trim();
      const correctionReason = correctionReasonSelect.value;
      const correctionNotes = correctionNotesTextarea.value.trim();

      if (!correctedValue || !correctionReason) {
        alert("修正後値と修正理由を入力してください");
        return;
      }

      // 修正履歴を保存（テーブルインデックス 1 = 受注データ修正履歴）
      const correctionRecord = {
        受注データID: row.受注データID,
        修正項目名: row.検証項目,
        修正前値: row.検証値,
        修正後値: correctedValue,
        修正理由: correctionReason,
        修正備考: correctionNotes,
        修正ユーザーID: "current-user-id",
        修正日時: new Date().toISOString(),
        検証結果ID: row.検証結果ID
      };

      const saved = await window.aivicApi.save(1, correctionRecord);
      if (saved) {
        // 検証結果の対応状況を「完了」に更新
        const updated = await window.aivicApi.update(0, row.検証結果ID, {
          対応状況: "完了",
          対応者ID: "current-user-id",
          対応完了日時: new Date().toISOString()
        });
        if (updated) {
          alert("修正が確認されました");
          // 一覧を再読み込み
          window.aivicApi.list(0).then(rows => {
            allRows = rows;
            renderRows(rows);
          });
        }
      }
    });

    rejectBtn.addEventListener("click", async () => {
      if (!confirm("この検証結果を却下しますか？")) return;

      const updated = await window.aivicApi.update(0, row.検証結果ID, {
        対応状況: "却下",
        対応者ID: "current-user-id",
        対応完了日時: new Date().toISOString()
      });
      if (updated) {
        alert("検証結果が却下されました");
        window.aivicApi.list(0).then(rows => {
          allRows = rows;
          renderRows(rows);
        });
      }
    });

    detailContent.innerHTML = "";
    detailContent.appendChild(clone);
  }

  // 3. 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    allRows = rows;
    renderRows(rows);
  });

  // 4. 検索ボタン
  container.querySelector("[data-testid='search-button']").addEventListener("click", () => {
    const statusFilter = container.querySelector("[data-testid='status-filter']").value;
    const severityFilter = container.querySelector("[data-testid='severity-filter']").value;
    const errorTypeFilter = container.querySelector("[data-testid='error-type-filter']").value;
    const responseStatusFilter = container.querySelector("[data-testid='response-status-filter']").value;

    const filtered = allRows.filter(r => {
      if (statusFilter && r.検証ステータス !== statusFilter) return false;
      if (severityFilter && r.重要度 !== severityFilter) return false;
      if (errorTypeFilter && (r.エラータイプ || r.検証ルールID) !== errorTypeFilter) return false;
      if (responseStatusFilter && r.対応状況 !== responseStatusFilter) return false;
      return true;
    });

    renderRows(filtered);
  });

  // 5. CSVエクスポート
  container.querySelector("[data-testid='export-button']").addEventListener("click", () => {
    const headers = ["優先度", "受注ID", "エラータイプ", "検証項目", "重要度", "ステータス", "信頼度スコア", "エラーメッセージ"];
    const rows = allRows.map(r => [
      r.優先度レベル || 3,
      (r.受注データID || '').substring(0, 8),
      r.エラータイプ || r.検証ルールID || '',
      r.検証項目 || '',
      r.重要度 || '',
      r.対応状況 || '',
      r.信頼度スコア || r.マッチング信頼度 || '',
      r.エラーメッセージ || ''
    ]);

    const csv = "\uFEFF" + [headers, ...rows].map(row => 
      row.map(cell => {
        const str = String(cell || '');
        return str.includes(',') || str.includes('"') || str.includes('\n') 
          ? '"' + str.replace(/"/g, '""') + '"' 
          : str;
      }).join(',')
    ).join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'validation_results_' + new Date().toISOString().split('T')[0] + '.csv';
    link.click();
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 0=受注データ修正履歴, 1=受注データ検証結果, 2=信頼度スコア, 3=チャネル情報
  const correctionHistoryTable = tables[0] || { records: [] };
  const validationResultTable = tables[1] || { records: [] };
  const trustScoreTable = tables[2] || { records: [] };
  const channelTable = tables[3] || { records: [] };

  // 修正項目テーブルの再描画
  function renderCorrectionItems(items) {
    const tbody = container.querySelector("#correction-items-tbody");
    if (!tbody) return;
    tbody.innerHTML = items.map(item => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 8px; color: var(--text);">${item.修正項目名 || ''}</td>
        <td style="padding: 8px; color: var(--text-muted);">${item.修正前値 || ''}</td>
        <td style="padding: 8px; color: #4caf50; font-weight: 500;">${item.修正後値 || ''}</td>
        <td style="padding: 8px; color: var(--text-muted); font-size: 11px;">${item.修正理由 || ''}</td>
      </tr>
    `).join('');
  }

  // 初期データ表示
  if (correctionHistoryTable.records && correctionHistoryTable.records.length > 0) {
    renderCorrectionItems(correctionHistoryTable.records);
  }

  // 保存ボタン
  const saveBtn = container.querySelector("[data-testid='save-button']");
  if (saveBtn) {
    saveBtn.addEventListener("click", async () => {
      const reason = container.querySelector("[data-testid='correction-reason-select']").value;
      const notes = container.querySelector("[data-testid='correction-notes']").value;

      if (!reason) {
        alert("修正理由を選択してください");
        return;
      }

      // 確認ダイアログ
      if (!confirm("修正内容を保存しますか？\n\n修正理由: " + reason + "\n\n保存後は修正履歴に記録されます。")) {
        return;
      }

      // 修正履歴を保存
      const correctionData = {
        受注データID: "ORD-2024-001234", // 実際には画面から取得
        修正項目名: "受注金額",
        修正前値: "¥150,000",
        修正後値: "¥155,000",
        修正理由: reason,
        修正備考: notes,
        修正ユーザーID: "user-001", // 実際にはセッションから取得
        修正日時: new Date().toISOString()
      };

      const saved = await window.aivicApi.save(0, correctionData);
      if (saved) {
        alert("修正内容を保存しました");
        // 修正履歴を再読み込み
        const updated = await window.aivicApi.list(0);
        if (updated) {
          renderCorrectionItems(updated);
        }
        // フォームをリセット
        container.querySelector("[data-testid='correction-reason-select']").value = "";
        container.querySelector("[data-testid='correction-notes']").value = "";
      }
    });
  }

  // キャンセルボタン
  const cancelBtn = container.querySelector("[data-testid='cancel-button']");
  if (cancelBtn) {
    cancelBtn.addEventListener("click", () => {
      if (confirm("修正内容を破棄して戻りますか？")) {
        window.showScreen("scr-1781413282852"); // 受注データ詳細確認・修正画面へ
      }
    });
  }

  // 初期データ読み込み（API から最新データを取得）
  window.aivicApi.list(0).then(rows => {
    if (rows && rows.length > 0) {
      renderCorrectionItems(rows);
    }
  }).catch(err => {
    console.log("修正履歴の読み込みに失敗しました（API未接続）");
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス（受注データ検証結果テーブルを想定）
  const tableIndex = 0;
  const tbody = container.querySelector("#order-status-tbody");

  // ステータスバッジの色付け
  function getStatusBadge(status) {
    const colors = {
      "合格": { bg: "rgba(76, 175, 80, 0.15)", text: "#4caf50" },
      "不合格": { bg: "rgba(244, 67, 54, 0.15)", text: "#f44336" },
      "警告": { bg: "rgba(255, 152, 0, 0.15)", text: "#ff9800" },
      "保留": { bg: "rgba(158, 158, 158, 0.15)", text: "#9e9e9e" }
    };
    const style = colors[status] || { bg: "rgba(200, 200, 200, 0.15)", text: "#c8c8c8" };
    return `<span style="background: ${style.bg}; color: ${style.text}; padding: 3px 6px; border-radius: 3px; font-size: 11px; font-weight: 600;">${status || "未判定"}</span>`;
  }

  // スコアバーの描画
  function getScoreBar(score) {
    const scoreNum = parseInt(score) || 0;
    const barColor = scoreNum >= 80 ? "#4caf50" : scoreNum >= 60 ? "#ff9800" : "#f44336";
    return `<div style="display: flex; align-items: center; gap: 6px;">
      <div style="width: 60px; height: 6px; background: rgba(200,200,200,0.2); border-radius: 3px; overflow: hidden;">
        <div style="width: ${scoreNum}%; height: 100%; background: ${barColor};"></div>
      </div>
      <span style="font-weight: 600; color: var(--text);">${scoreNum}</span>
    </div>`;
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = `<tr style="border-bottom: 1px solid var(--border);"><td colspan="7" style="padding: 16px; text-align: center; color: var(--text-muted);">データがありません</td></tr>`;
      updateKpis([]);
      return;
    }

    tbody.innerHTML = rows.map(r => {
      const orderId = r.受注データID || r.order_id || r.id || "N/A";
      const orderDate = r.受注日時 || r.order_date || "N/A";
      const channel = r.チャネル名 || r.channel || "N/A";
      const status = r.検証ステータス || r.status || "未判定";
      const score = r.信頼度スコア || r.score || 0;
      const validationResult = r.検証結果 || r.validation_result || "未検証";

      return `<tr style="border-bottom: 1px solid var(--border); background: var(--bg-main);" data-id="${orderId}">
        <td style="padding: 8px; color: var(--text); font-family: monospace; font-size: 11px;">${orderId.substring(0, 12)}...</td>
        <td style="padding: 8px; color: var(--text); font-size: 11px;">${orderDate}</td>
        <td style="padding: 8px; color: var(--text); font-size: 11px;">${channel}</td>
        <td style="padding: 8px;">${getStatusBadge(status)}</td>
        <td style="padding: 8px; text-align: center;">${getScoreBar(score)}</td>
        <td style="padding: 8px; color: var(--text-muted); font-size: 11px;">${validationResult}</td>
        <td style="padding: 8px; text-align: center;">
          <button class="action-btn secondary detail-btn" data-id="${orderId}" style="padding: 4px 8px; font-size: 11px;">詳細</button>
          <button class="action-btn secondary history-btn" data-id="${orderId}" style="padding: 4px 8px; font-size: 11px; margin-left: 4px;">履歴</button>
        </td>
      </tr>`;
    }).join("");

    updateKpis(rows);
  }

  // KPI 更新関数
  function updateKpis(rows) {
    const verified = rows.filter(r => r.検証ステータス === "合格" || r.status === "合格").length;
    const warnings = rows.filter(r => r.検証ステータス === "警告" || r.status === "警告").length;
    const avgScore = rows.length > 0 
      ? Math.round(rows.reduce((sum, r) => sum + (parseInt(r.信頼度スコア || r.score || 0)), 0) / rows.length)
      : 0;
    const pendingFix = rows.filter(r => r.対応状況 === "未対応" || r.response_status === "未対応").length;

    container.querySelector("[data-testid='kpi-verified']").textContent = verified;
    container.querySelector("[data-testid='kpi-warnings']").textContent = warnings;
    container.querySelector("[data-testid='kpi-avg-score']").textContent = avgScore;
    container.querySelector("[data-testid='kpi-pending-fix']").textContent = pendingFix;
  }

  // 初期データ描画
  renderRows(tables[tableIndex]?.records || []);

  // 検索ボタン
  container.querySelector("[data-testid='search-button']").addEventListener("click", async () => {
    const orderId = container.querySelector("[data-testid='filter-order-id']").value.trim();
    const dateFrom = container.querySelector("[data-testid='filter-date-from']").value;
    const dateTo = container.querySelector("[data-testid='filter-date-to']").value;
    const status = container.querySelector("[data-testid='filter-status']").value;
    const channel = container.querySelector("[data-testid='filter-channel']").value;
    const scoreMin = parseInt(container.querySelector("[data-testid='filter-score-min']").value) || 0;
    const scoreMax = parseInt(container.querySelector("[data-testid='filter-score-max']").value) || 100;

    const rows = await window.aivicApi.list(tableIndex);
    if (!rows) return;

    const filtered = rows.filter(r => {
      const rOrderId = (r.受注データID || r.order_id || r.id || "").toLowerCase();
      const rDate = r.受注日時 || r.order_date || "";
      const rChannel = r.チャネル名 || r.channel || "";
      const rStatus = r.検証ステータス || r.status || "";
      const rScore = parseInt(r.信頼度スコア || r.score || 0);

      if (orderId && !rOrderId.includes(orderId.toLowerCase())) return false;
      if (dateFrom && rDate < dateFrom) return false;
      if (dateTo && rDate > dateTo) return false;
      if (status && rStatus !== status) return false;
      if (channel && rChannel !== channel) return false;
      if (rScore < scoreMin || rScore > scoreMax) return false;

      return true;
    });

    renderRows(filtered);
  });

  // リセットボタン
  container.querySelector("[data-testid='reset-button']").addEventListener("click", () => {
    container.querySelector("[data-testid='filter-order-id']").value = "";
    container.querySelector("[data-testid='filter-date-from']").value = "";
    container.querySelector("[data-testid='filter-date-to']").value = "";
    container.querySelector("[data-testid='filter-status']").value = "";
    container.querySelector("[data-testid='filter-channel']").value = "";
    container.querySelector("[data-testid='filter-score-min']").value = "";
    container.querySelector("[data-testid='filter-score-max']").value = "";
    renderRows(tables[tableIndex]?.records || []);
  });

  // CSVエクスポートボタン
  container.querySelector("[data-testid='export-csv-button']").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(tableIndex);
    if (!rows || rows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["受注ID", "受注日時", "チャネル", "検証ステータス", "信頼度スコア", "検証結果", "対応状況"];
    const csvContent = [
      "\uFEFF" + headers.join(","),
      ...rows.map(r => [
        r.受注データID || r.order_id || r.id || "",
        r.受注日時 || r.order_date || "",
        r.チャネル名 || r.channel || "",
        r.検証ステータス || r.status || "",
        r.信頼度スコア || r.score || "",
        r.検証結果 || r.validation_result || "",
        r.対応状況 || r.response_status || ""
      ].map(v => `"${String(v).replace(/"/g, '""')}"`).join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `order-status-${new Date().toISOString().split("T")[0]}.csv`;
    link.click();
  });

  // ダッシュボードボタン
  container.querySelector("[data-testid='dashboard-button']").addEventListener("click", () => {
    window.showScreen("scr-1781413262699");
  });

  // 詳細ボタン（イベントデリゲーション）
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const orderId = detailBtn.dataset.id;
      window.showScreen("scr-1781413282852", { orderId });
    }

    const historyBtn = e.target.closest(".history-btn");
    if (historyBtn) {
      const orderId = historyBtn.dataset.id;
      // 修正履歴画面へ遷移（適切な画面IDを選択）
      window.showScreen("scr-1781413354977", { orderId });
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス（tables 引数から推測）
  const validationResultsIdx = 0;  // 受注データ検証結果
  const correctionHistoryIdx = 1;  // 受注データ修正履歴
  const confidenceScoreIdx = 2;    // 信頼度スコア
  const ocrResultIdx = 3;          // AI_OCR読み込み結果
  const voiceGuidanceIdx = 4;      // 音声ガイダンス記録
  const channelIdx = 5;            // チャネル情報
  const duplicateDetectionIdx = 6; // 重複受注検出結果
  const conflictDetectionIdx = 7;  // チャネル間矛盾検出結果
  const missingDetectionIdx = 8;   // 入力漏れ検出結果
  const priorityListIdx = 9;       // 修正対象優先度リスト

  // ===== 1. 再描画関数 =====
  function renderPriorityTable(rows) {
    const tbody = container.querySelector("#priority-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.04);"><td colspan="5" style="padding: 12px; text-align: center; color: var(--text-muted);">修正対象なし</td></tr>';
      return;
    }
    tbody.innerHTML = rows.slice(0, 10).map(r => {
      const priorityLabel = ['最高', '高', '中', '低', '最低'][r.優先度レベル - 1] || '—';
      const statusColor = r.修正ステータス === '完了' ? '#4ade80' : r.修正ステータス === '対応中' ? '#fbbf24' : '#9ca3af';
      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.04);">
          <td style="padding: 8px; color: var(--text);">${priorityLabel}</td>
          <td style="padding: 8px; color: var(--text);">${r.エラー分類 || '—'}</td>
          <td style="padding: 8px; color: ${statusColor}; font-weight: 500;">${r.修正ステータス || '—'}</td>
          <td style="padding: 8px; color: var(--text);">${r.信頼度スコア || '—'}%</td>
          <td style="padding: 8px;"><button class="action-btn secondary edit-priority-btn" data-id="${r.優先度リストID}" style="padding: 4px 8px; font-size: 11px; cursor: pointer;">編集</button></td>
        </tr>
      `;
    }).join("");
  }

  function renderErrorTimeline(errors) {
    const timeline = container.querySelector("#error-timeline");
    if (!errors || errors.length === 0) {
      timeline.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); text-align: center; padding: 20px 0;">エラーなし</div>';
      return;
    }
    timeline.innerHTML = errors.slice(0, 8).map(e => {
      const severityColor = e.重要度 === '致命的' ? '#ef4444' : e.重要度 === '高' ? '#f97316' : e.重要度 === '中' ? '#fbbf24' : '#9ca3af';
      return `
        <div style="background: rgba(0,0,0,0.25); border-left: 3px solid ${severityColor}; border-radius: 3px; padding: 8px; font-size: 11px;">
          <div style="color: ${severityColor}; font-weight: 600; margin-bottom: 2px;">${e.エラーコード || 'ERR'}</div>
          <div style="color: var(--text); margin-bottom: 2px;">${e.エラーメッセージ || e.検証項目 || '—'}</div>
          <div style="color: var(--text-muted); font-size: 10px;">対応: ${e.対応状況 || '未対応'}</div>
        </div>
      `;
    }).join("");
  }

  // ===== 2. 初期データ読み込み =====
  async function initializeData() {
    try {
      const validationResults = await window.aivicApi.list(validationResultsIdx);
      const priorityList = await window.aivicApi.list(priorityListIdx);
      const duplicates = await window.aivicApi.list(duplicateDetectionIdx);
      const conflicts = await window.aivicApi.list(conflictDetectionIdx);
      const missing = await window.aivicApi.list(missingDetectionIdx);

      // 検証エラー表示
      const errors = (validationResults || []).filter(v => v.検証ステータス !== '合格');
      renderErrorTimeline(errors);

      // 修正優先度リスト表示
      renderPriorityTable(priorityList || []);

      // 検出結果サマリー
      container.querySelector("#duplicate-count").textContent = (duplicates || []).filter(d => d.検出ステータス === '未確認').length + '件';
      container.querySelector("#conflict-count").textContent = (conflicts || []).filter(c => c.ステータス === '未対応').length + '件';
      container.querySelector("#missing-count").textContent = (missing || []).filter(m => m.検出ステータス === '未対応').length + '件';

      // 信頼度スコア表示
      const confidenceScores = await window.aivicApi.list(confidenceScoreIdx);
      if (confidenceScores && confidenceScores.length > 0) {
        const latestScore = confidenceScores[confidenceScores.length - 1];
        container.querySelector("#overall-score").textContent = latestScore.総合スコア || '—';
        container.querySelector("#completeness-score").textContent = latestScore.完全性スコア || '—';
      }
    } catch (e) {
      console.error("初期化エラー:", e);
    }
  }

  initializeData();

  // ===== 3. AI_OCR実行ボタン =====
  container.querySelector("#btn-ocr").addEventListener("click", async () => {
    const channel = container.querySelector("#channel-select").value;
    const customerName = container.querySelector("#customer-name").value;
    const phone = container.querySelector("#phone").value;
    const amount = container.querySelector("#order-amount").value;
    const address = container.querySelector("#address").value;

    if (!channel || !customerName) {
      alert("チャネルと顧客名を入力してください");
      return;
    }

    // OCR結果をシミュレート
    const ocrData = {
      order_id: "order-" + Date.now(),
      source_document_type: "注文書",
      ocr_engine_version: "v2.1",
      raw_ocr_text: `顧客名: ${customerName}\n電話: ${phone}\n金額: ${amount}\n住所: ${address}`,
      extracted_fields: JSON.stringify({ customerName, phone, amount, address }),
      overall_confidence: Math.floor(Math.random() * 40 + 60),
      processing_status: "成功",
      requires_manual_review: false,
      processing_timestamp: new Date().toISOString(),
      created_by: "system"
    };

    const saved = await window.aivicApi.save(ocrResultIdx, ocrData);
    if (saved) {
      container.querySelector("#preview-data").textContent = ocrData.raw_ocr_text;
      container.querySelector("#overall-score").textContent = ocrData.overall_confidence;
      alert("AI_OCR読み込み完了");
      initializeData();
    }
  });

  // ===== 4. 音声ガイダンス再生ボタン =====
  container.querySelector("#btn-voice").addEventListener("click", async () => {
    const channel = container.querySelector("#channel-select").value;
    if (!channel) {
      alert("チャネルを選択してください");
      return;
    }

    const voiceData = {
      受注ID: "order-" + Date.now(),
      ガイダンスタイプ: "IVR_確認",
      ガイダンス内容: "ご注文ありがとうございます。ご注文内容をご確認ください。",
      再生開始時刻: new Date().toISOString(),
      再生時間秒: 5,
      応答確認状態: "確認済",
      品質問題フラグ: false,
      作成者: "system"
    };

    const saved = await window.aivicApi.save(voiceGuidanceIdx, voiceData);
    if (saved) {
      alert("音声ガイダンス再生完了");
    }
  });

  // ===== 5. 正規化ルール適用ボタン =====
  container.querySelector("#btn-normalize").addEventListener("click", async () => {
    const customerName = container.querySelector("#customer-name").value;
    const phone = container.querySelector("#phone").value;
    const amount = container.querySelector("#order-amount").value;

    if (!customerName || !phone || !amount) {
      alert("必須項目を入力してください");
      return;
    }

    // 正規化後の検証結果を作成
    const validationResult = {
      受注データID: "order-" + Date.now(),
      検証ステータス: "合格",
      検証ルールID: "rule-normalize-001",
      検証項目: "顧客名,電話番号,金額",
      検証値: `${customerName},${phone},${amount}`,
      期待値: "正規化済み",
      重要度: "高",
      検証実行日時: new Date().toISOString(),
      作成者ID: "system"
    };

    const saved = await window.aivicApi.save(validationResultsIdx, validationResult);
    if (saved) {
      alert("正規化ルール適用完了");
      initializeData();
    }
  });

  // ===== 6. 詳細表示ボタン =====
  container.querySelector("#btn-view-duplicate").addEventListener("click", () => {
    window.showScreen("scr-1781413297335");
  });

  container.querySelector("#btn-view-conflict").addEventListener("click", () => {
    window.showScreen("scr-1781413311177");
  });

  container.querySelector("#btn-view-missing").addEventListener("click", () => {
    window.showScreen("scr-1781413340116");
  });

  // ===== 7. 修正優先度リスト編集 =====
  container.addEventListener("click", async (e) => {
    const editBtn = e.target.closest(".edit-priority-btn");
    if (editBtn) {
      const priorityId = editBtn.dataset.id;
      window.showScreen("scr-1781413354977");
