function(container, apiUrl, tables) {
  // テーブルインデックス
  const VALIDATION_RESULTS_IDX = 0;
  const PRIORITY_LIST_IDX = 1;

  // 初期データ
  let allValidationResults = (tables[VALIDATION_RESULTS_IDX]?.records || []);
  let allPriorityList = (tables[PRIORITY_LIST_IDX]?.records || []);
  let selectedRowId = null;

  // ============ 1. 再描画関数 ============
  function renderValidationRows(rows) {
    const tbody = container.querySelector("#record-tbody");
    tbody.innerHTML = rows.map(r => {
      const statusColor = r.検証ステータス === "合格" ? "#4ade80" : 
                          r.検証ステータス === "不合格" ? "#ef4444" : 
                          r.検証ステータス === "警告" ? "#f59e0b" : "#6b7280";
      const severityColor = r.重要度 === "致命的" ? "#dc2626" : 
                            r.重要度 === "高" ? "#f97316" : 
                            r.重要度 === "中" ? "#eab308" : "#10b981";
      return `
        <tr data-id="${r.検証結果ID || r.id}" style="border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.15s;" onmouseover="this.style.background='rgba(255,255,255,0.04)'" onmouseout="this.style.background=''">
          <td style="padding: 8px 12px; color: var(--text);">${(r.受注データID || r.id || "").substring(0, 8)}</td>
          <td style="padding: 8px 12px;">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${statusColor}22; color: ${statusColor}; font-size: 11px; font-weight: 600;">${r.検証ステータス || "-"}</span>
          </td>
          <td style="padding: 8px 12px; color: var(--text); font-weight: 500;">${r.総合スコア || r.信頼度スコア || "-"}</td>
          <td style="padding: 8px 12px; color: var(--text);">${r.チャネル || "-"}</td>
          <td style="padding: 8px 12px;">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${severityColor}22; color: ${severityColor}; font-size: 11px; font-weight: 600;">${r.重要度 || "-"}</span>
          </td>
          <td style="padding: 8px 12px; color: var(--text);">${r.対応状況 || "-"}</td>
        </tr>
      `;
    }).join("");
    container.querySelector("#record-count").textContent = rows.length + "件";
  }

  function renderPriorityRows(rows) {
    const tbody = container.querySelector("#priority-tbody");
    tbody.innerHTML = rows.slice(0, 8).map(r => {
      const priorityColor = r.優先度レベル === 1 ? "#dc2626" : 
                            r.優先度レベル === 2 ? "#f97316" : 
                            r.優先度レベル === 3 ? "#eab308" : "#10b981";
      return `
        <tr style="border-bottom: 1px solid var(--border);">
          <td style="padding: 6px 10px;">
            <span style="display: inline-block; width: 24px; height: 24px; border-radius: 50%; background: ${priorityColor}; color: #fff; font-size: 11px; font-weight: 700; text-align: center; line-height: 24px;">${r.優先度レベル || "-"}</span>
          </td>
          <td style="padding: 6px 10px; color: var(--text);">${(r.受注データID || r.id || "").substring(0, 8)}</td>
          <td style="padding: 6px 10px; color: var(--text); font-size: 11px;">${r.エラー分類 || "-"}</td>
          <td style="padding: 6px 10px; color: var(--text); font-size: 11px;">${r.修正ステータス || "-"}</td>
          <td style="padding: 6px 10px; text-align: center; color: var(--text); font-weight: 600;">${r.ビジネスインパクト度 || "-"}</td>
          <td style="padding: 6px 10px; text-align: center;">
            <button class="action-btn secondary priority-edit-btn" data-id="${r.優先度リストID || r.id}" style="padding: 3px 6px; font-size: 11px;">修正</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  function showDetailPanel(rowId) {
    selectedRowId = rowId;
    const row = allValidationResults.find(r => (r.検証結果ID || r.id) === rowId);
    if (!row) return;

    const template = container.querySelector("#detail-template");
    const clone = template.content.cloneNode(true);

    clone.querySelector(".detail-order-id").textContent = row.受注データID || row.id || "-";
    clone.querySelector(".detail-status").textContent = row.検証ステータス || "-";
    clone.querySelector(".detail-score").textContent = (row.総合スコア || row.信頼度スコア || "-") + (row.総合スコア ? "/100" : "");
    clone.querySelector(".detail-item").textContent = row.検証項目 || "-";
    clone.querySelector(".detail-error-code").textContent = row.エラーコード || "-";
    clone.querySelector(".detail-error-msg").textContent = row.エラーメッセージ || "-";
    clone.querySelector(".detail-expected").textContent = row.期待値 || "-";
    clone.querySelector(".detail-actual").textContent = row.検証値 || "-";
    clone.querySelector(".detail-severity").textContent = row.重要度 || "-";
    clone.querySelector(".detail-response-status").textContent = row.対応状況 || "-";
    clone.querySelector(".detail-timestamp").textContent = row.検証実行日時 ? new Date(row.検証実行日時).toLocaleString("ja-JP") : "-";

    const detailPanel = container.querySelector("#detail-panel");
    detailPanel.innerHTML = "";
    detailPanel.appendChild(clone);

    // ボタンイベント
    detailPanel.querySelector("[data-testid='detail-edit-button']").addEventListener("click", () => {
      window.showScreen("scr-1781413282852"); // 受注データ詳細確認・修正画面
    });
    detailPanel.querySelector("[data-testid='detail-approve-button']").addEventListener("click", () => {
      alert("承認処理を実行します");
      window.aivicApi.update(VALIDATION_RESULTS_IDX, rowId, { 対応状況: "完了" }).then(() => {
        window.aivicApi.list(VALIDATION_RESULTS_IDX).then(rows => {
          allValidationResults = rows;
          renderValidationRows(allValidationResults);
        });
      });
    });
    detailPanel.querySelector("[data-testid='detail-reject-button']").addEventListener("click", () => {
      alert("却下処理を実行します");
      window.aivicApi.update(VALIDATION_RESULTS_IDX, rowId, { 対応状況: "却下" }).then(() => {
        window.aivicApi.list(VALIDATION_RESULTS_IDX).then(rows => {
          allValidationResults = rows;
          renderValidationRows(allValidationResults);
        });
      });
    });
  }

  // ============ 2. 初期データ描画 ============
  renderValidationRows(allValidationResults);
  renderPriorityRows(allPriorityList);

  // ============ 3. 検索・フィルタ ============
  container.querySelector("[data-testid='search-button']").addEventListener("click", () => {
    const statusVal = container.querySelector("[data-testid='status-filter']").value;
    const channelVal = container.querySelector("[data-testid='channel-filter']").value;
    const scoreVal = container.querySelector("[data-testid='score-filter']").value;
    const keywordVal = container.querySelector("[data-testid='search-input']").value.toLowerCase();

    let filtered = allValidationResults.filter(r => {
      if (statusVal && r.検証ステータス !== statusVal) return false;
      if (channelVal && r.チャネル !== channelVal) return false;
      if (scoreVal) {
        const score = r.総合スコア || r.信頼度スコア || 0;
        const [min, max] = scoreVal.split("-").map(Number);
        if (score < min || score > max) return false;
      }
      if (keywordVal && !JSON.stringify(r).toLowerCase().includes(keywordVal)) return false;
      return true;
    });

    renderValidationRows(filtered);
  });

  container.querySelector("[data-testid='reset-button']").addEventListener("click", () => {
    container.querySelector("[data-testid='status-filter']").value = "";
    container.querySelector("[data-testid='channel-filter']").value = "";
    container.querySelector("[data-testid='score-filter']").value = "";
    container.querySelector("[data-testid='search-input']").value = "";
    renderValidationRows(allValidationResults);
  });

  // ============ 4. CSVエクスポート ============
  container.querySelector("[data-testid='export-button']").addEventListener("click", () => {
    const rows = allValidationResults;
    const headers = ["受注データID", "検証ステータス", "信頼度スコア", "チャネル", "重要度", "対応状況", "検証項目", "エラーコード", "エラーメッセージ"];
    const csv = [
      "\uFEFF" + headers.join(","),
      ...rows.map(r => [
        r.受注データID || r.id || "",
        r.検証ステータス || "",
        r.総合スコア || r.信頼度スコア || "",
        r.チャネル || "",
        r.重要度 || "",
        r.対応状況 || "",
        r.検証項目 || "",
        r.エラーコード || "",
        (r.エラーメッセージ || "").replace(/"/g, '""')
      ].map(v => typeof v === "string" && v.includes(",") ? `"${v}"` : v).join(","))
    ].join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "validation_results_" + new Date().toISOString().split("T")[0] + ".csv";
    link.click();
  });

  // ============ 5. 行クリックで詳細表示 ============
  container.addEventListener("click", e => {
    const tr = e.target.closest("tbody tr");
    if (tr) {
      const rowId = tr.dataset.id;
      showDetailPanel(rowId);
    }
  });

  // ============ 6. 優先度リスト更新ボタン ============
  container.querySelector("[data-testid='priority-refresh-button']").addEventListener("click", () => {
    window.aivicApi.list(PRIORITY_LIST_IDX).then(rows => {
      allPriorityList = rows;
      renderPriorityRows(allPriorityList);
    });
  });

  // ============ 7. 優先度リスト行の修正ボタン ============
  container.addEventListener("click", e => {
    const btn = e.target.closest(".priority-edit-btn");
    if (btn) {
      const priorityId = btn.dataset.id;
      window.showScreen("scr-1781413354977"); // 修正対象優先度リスト画面
    }
  });
}
